function planEditor(id){const r=currentPlan().find(x=>x.id===id)||{exerciseId:state.exercises[0]?.id,targetSets:2,repMin:6,repMax:10,rest:90,notes:''};if(!state.exercises.length){toast('ابتدا یک حرکت در بانک تعریف کن.');return;}modal(`${id?'ویرایش':'افزودن'} حرکت · ${days[planDay]}`,`<form id="plan-form" data-id="${id||''}">${chooserHTML(r.exerciseId)}<div class="form-grid three">${field('تعداد ست اصلی',number('targetSets',r.targetSets,'required'))}${field('حداقل تکرار',number('repMin',r.repMin,'required'))}${field('حداکثر تکرار',number('repMax',r.repMax,'required'))}${field('استراحت (ثانیه)',number('rest',r.rest,'required'))}</div>${field('یادداشت این حرکت در برنامه',`<textarea maxlength="10000" name="notes" rows="3">${esc(r.notes)}</textarea>`)}<div class="form-actions"><button class="btn primary" type="submit">ذخیره در برنامه</button></div></form>`);$('#modal').classList.add('catalog-modal');}



function profileEditor(){const p=state.profile;modal('پروفایل شخصی',`<form id="profile-form"><div class="form-grid">${field('نام (اختیاری)',input('name',p.name,'maxlength="80"'))}${field('قد به سانتی‌متر (اختیاری)',number('height',p.height))}${field('جنسیت (اختیاری)',`<select name="gender">${['','مرد','زن','سایر','ترجیح می‌دهم نگویم'].map(v=>`<option ${p.gender===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`)}${field('هدف شخصی',input('goal',p.goal,'maxlength="200" placeholder="مثلاً پیگیری قدرت و اندازه‌ها"'))}</div><p class="tiny muted">وزن را در «ثبت اندازه‌های جدید» وارد کن تا تاریخچه داشته باشد.</p><div class="form-actions"><button class="btn primary" type="submit">ذخیرهٔ پروفایل</button></div></form>`);}
function measurementEditor(id){const x=state.measurements.find(x=>x.id===id)||{date:C.today(),values:{},notes:''};modal(id?'ویرایش اندازه‌گیری':'ثبت اندازه‌های جدید',`<form id="measurement-form" data-id="${id||''}">${field('تاریخ اندازه‌گیری',dateInput('date',x.date,'required'))}<div class="form-grid">${state.measurementTypes.map(t=>field(`${esc(t.name)} (${t.unit==='kg'?'کیلوگرم':'سانتی‌متر'})`,number(t.id,x.values[t.id]??'','data-measure placeholder="اختیاری"'))).join('')}</div>${field('یادداشت',`<textarea maxlength="10000" name="notes" rows="2">${esc(x.notes)}</textarea>`)}<p class="tiny muted">فقط شاخص‌های موردنظرت را وارد کن. برای مقایسهٔ قابل اتکا، شرایط اندازه‌گیری را یکسان نگه دار.</p><div class="form-actions">${btn('تعریف شاخص جدید','measure-type-new','ghost')}<button class="btn primary" type="submit">ذخیرهٔ اندازه‌ها</button></div></form>`);}
function measureTypes(){modal('شاخص‌های بدن',`<div class="stack">${state.measurementTypes.map(t=>`<div class="row spread"><b>${esc(t.name)} <small class="muted">${t.unit==='kg'?'کیلوگرم':'سانتی‌متر'}</small></b><div class="row">${btn(icon('edit'),'measure-type-edit','icon-btn',`data-id="${t.id}" aria-label="ویرایش شاخص"`)}${btn(icon('trash'),'measure-type-delete','icon-btn',`data-id="${t.id}" aria-label="حذف شاخص"`)}</div></div>`).join('')}</div><div class="form-actions">${btn('شاخص جدید','measure-type-new','primary')}</div>`);}
function measureTypeEditor(id){const t=mt(id)||{name:'',unit:'cm'};const used=id&&(id==='weight'||state.measurements.some(x=>x.values[id]!=null));modal('تعریف شاخص بدن',`<form id="measure-type-form" data-id="${id||''}">${field('نام شاخص',input('name',t.name,'required maxlength="80" placeholder="مثلاً دور بازوی چپ"'))}${field('واحد',`<select name="unit" ${used?'disabled':''}><option value="cm" ${t.unit==='cm'?'selected':''}>سانتی‌متر</option><option value="kg" ${t.unit==='kg'?'selected':''}>کیلوگرم</option></select>`)}${used?'<p class="tiny muted">برای حفظ معنای تاریخچه، واحد شاخصِ استفاده‌شده قابل تغییر نیست.</p>':''}<div class="form-actions"><button class="btn primary" type="submit">ذخیرهٔ شاخص</button></div></form>`);}

