let planPeriodId=C.periodForDate(state,C.today())?.id||state.periods[0]?.id||'',planMode='template',planDate=C.today(),planScope='',historyPeriod='',historyMonth='',progressTrainingPeriod='',comparisonDate=C.today(),bulkPreview=null;
const programContext=()=>state.periods.find(p=>p.id===planPeriodId)||state;
const draftContext=()=>C.contextForDate(state,draft?.date||C.today());
const jparts=d=>C.toPersianParts(d);
const localDigits=v=>String(v).replace(/\d+/g,d=>L.number(Number(d),0,false));
function parseJDate(value){return L.parseDate(value);}
const jdate=d=>{const p=C.calendarParts(d,L.calendar());return p?`${p.year}/${String(p.month).padStart(2,'0')}/${String(p.day).padStart(2,'0')}`:'';};
const jfile=()=>jdate(C.today()).replaceAll('/','-');
const months=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];


function periodRange(p){return `${dateLabel(p.startDate,true)} تا ${p.endDate?dateLabel(p.endDate,true):'بدون تاریخ پایان'}`;}
function allWeeks(){const map=new Map();[...state.weekTypes,...state.periods.flatMap(p=>p.weekTypes)].forEach(w=>{if(!map.has(w.id))map.set(w.id,w);});return [...map.values()];}
function currentPlan(){const p=programContext();if(planMode==='template')return p.plans[planWeek]?.[planDay]||[];if(planScope==='day'&&Object.hasOwn(p.dayOverrides||{},planDate))return p.dayOverrides[planDate];if(planScope==='week'&&p.weekOverrides?.[weekStart(planDate)]?.days[dayOf(planDate)])return p.weekOverrides[weekStart(planDate)].days[dayOf(planDate)];return C.planForDate(state,planDate).exercises;}
function canEditPlan(){const p=programContext();return !!p.id&&(planMode==='template'||(planScope==='day'&&Object.hasOwn(p.dayOverrides,planDate))||(planScope==='week'&&!!p.weekOverrides[weekStart(planDate)]));}
function setCurrentPlan(entries){const p=programContext();if(!canEditPlan())return false;if(planMode==='template'){p.plans[planWeek]??={};p.plans[planWeek][planDay]=entries;}else if(planScope==='day')p.dayOverrides[planDate]=entries;else p.weekOverrides[weekStart(planDate)].days[dayOf(planDate)]=entries;return true;}
function selectPlanDate(date){planDate=date;const p=C.periodForDate(state,date);if(p)planPeriodId=p.id;planWeek=C.weekTypeFor(state,date).id;planDay=dayOf(date);planScope=p&&Object.hasOwn(p.dayOverrides,date)?'day':p?.weekOverrides[weekStart(date)]?'week':'';}
function planUsage(exerciseId){const contexts=[state,...state.periods];return contexts.some(p=>Object.values(p.plans).some(w=>Object.values(w).some(d=>d.some(x=>x.exerciseId===exerciseId)))||Object.values(p.dayOverrides||{}).some(d=>d.some(x=>x.exerciseId===exerciseId))||Object.values(p.weekOverrides||{}).some(w=>Object.values(w.days).some(d=>d.some(x=>x.exerciseId===exerciseId))));}

function program(){const pc=programContext(),isPeriod=!!pc.id;if(!pc.weekTypes.some(w=>w.id===planWeek))planWeek=pc.weekTypes[0].id;const resolved=C.planForDate(state,planDate),datePeriod=C.periodForDate(state,planDate),active=isPeriod&&(planMode==='template'||datePeriod?.id===pc.id),w=planMode==='template'?week(planWeek):C.weekTypeFor(state,planDate),list=active?currentPlan():[],editable=active&&canEditPlan(),scopeLabel=planMode==='template'?'الگوی تکرارشوندهٔ این دوره':planScope==='day'?'ویرایش فقط همین روز':planScope==='week'?'ویرایش همین هفته':'برنامهٔ مؤثر این تاریخ';return heading('دوره‌های مستقل، برنامه‌های منعطف','دوره‌ها و برنامه‌ها','برنامهٔ هر دوره جداست؛ استثنای یک روز یا یک هفته روی بقیهٔ تقویم اثر نمی‌گذارد.',btn(icon('plus')+' دورهٔ جدید','period-new','primary'))+`
<section class="card"><div class="filter-bar">${field('دورهٔ تمرینی',`<select id="plan-period">${options(state.periods,planPeriodId)}</select>`)}${btn('مدیریت دوره‌ها','periods-manage','secondary')}${isPeriod?btn(icon('edit')+' ویرایش دوره','period-edit','ghost small',`data-id="${pc.id}"`):''}</div>${isPeriod?`<p class="tiny muted">${periodRange(pc)} · شروع چرخه: ${dateLabel(pc.cycleAnchor,true)} · ${pc.weekTypes.map(x=>esc(x.name)).join(' ← ')} ← تکرار</p>`:''}<div class="segmented plan-modes">${btn('الگوی پایهٔ دوره','plan-mode',planMode==='template'?'active':'','data-value="template"')}${btn('تقویم و تغییرات روز / هفته','plan-mode',planMode==='calendar'?'active':'','data-value="calendar"')}</div></section>
${isPeriod?periodMapPanelHTML(pc):''}
${!isPeriod?`<section class="card">${empty('دوره‌ای تعریف نشده','اولین دوره را با تاریخ شروع و برنامهٔ دلخواهت بساز.',btn('تعریف دوره','period-new','primary'))}</section>`:`${planMode==='template'?`<div class="tabs">${pc.weekTypes.map(w=>btn(esc(w.name),'plan-week',`tab ${planWeek===w.id?'active':''}`,`data-id="${w.id}"`)).join('')}</div>`:`<section class="card"><div class="filter-bar">${field('تاریخ روز موردنظر',dateInput('planDate',planDate,'id="plan-date" required'))}${btn('هفتهٔ قبل','calendar-prev','ghost small')}${btn('امروز','calendar-today','ghost small')}${btn('هفتهٔ بعد','calendar-next','ghost small')}</div>${calendarStrip()}<div class="row wrap"><span class="badge lime">${esc(resolved.weekTypeName)}</span><span class="badge">${{day:'استثنای روز',week:'استثنای هفته',period:'الگوی دوره',none:'بدون برنامه'}[resolved.source]}</span><span class="tiny muted">${dateLabel(planDate)}</span></div>${active?`<div class="row wrap override-actions">${btn('تغییر فقط همین روز','override-day-create',planScope==='day'?'primary small':'secondary small')}${btn('تغییر این هفته','override-week-create',planScope==='week'?'primary small':'secondary small')}${btn('این روز استراحت است','override-rest','ghost small')}${Object.hasOwn(pc.dayOverrides,planDate)?btn('برداشتن استثنای روز','override-day-clear','ghost small'):''}${pc.weekOverrides[weekStart(planDate)]?btn('برداشتن استثنای هفته','override-week-clear','ghost small'):''}</div>`:'<p class="notice warning">این تاریخ در دورهٔ انتخاب‌شده نیست. تاریخ یا دوره را تغییر بده یا یک دوره برای آن بازه بساز.</p>'}${active&&planScope==='week'?field('نوع هفته فقط برای این هفته',`<select id="override-week-type">${options(pc.weekTypes,pc.weekOverrides[weekStart(planDate)].weekTypeId)}</select>`):''}</section>`}
<section class="card"><div class="card-head"><div><h2>${scopeLabel}</h2><p class="card-sub" data-keep-visible>${planMode==='template'?`${esc(pc.name)} · ${esc(w.name)} · ${days[planDay]}`:dateLabel(planDate)}</p></div><div class="row wrap">${planMode==='template'?btn('مدیریت هفته‌های این دوره','weeks-manage','ghost small'):''}${editable?btn(icon('plus')+' افزودن حرکت','plan-add','secondary small'):''}</div></div>${planMode==='template'?weekStrip(planDay,'plan-day'):''}${editable?`<div class="notice ${planMode==='calendar'?'success':''}" data-keep-visible>${planMode==='template'?'ویرایش این بخش، الگوی پایهٔ همین دوره را تغییر می‌دهد. جلسه‌های ثبت‌شده مستقل می‌مانند.':planScope==='day'?'فقط همین تاریخ تغییر می‌کند؛ حتی برنامهٔ هفته هم عوض نمی‌شود.':'تغییر این برنامه فقط برای همین هفته در همین دوره است. اگر روزی استثنای جدا دارد، استثنای روز اولویت دارد.'}</div>`:'<p class="tiny muted">برای تغییر برنامه، ابتدا «تغییر فقط همین روز» یا «تغییر این هفته» را انتخاب کن.</p>'}
${list.length?`<div class="stack">${list.map((r,i)=>`<div class="plan-row"><div class="row"><span class="exercise-number">${fa(i+1)}</span><div><b>${esc(ex(r.exerciseId)?.name||'حرکت')}</b><p class="tiny muted">${fa(r.targetSets)} ست اصلی · ${fa(r.repMin)} تا ${fa(r.repMax)} تکرار · ${fa(r.rest)} ثانیه استراحت</p>${r.notes?`<p class="tiny user-text" data-no-i18n>${esc(r.notes)}</p>`:''}</div></div>${editable?`<div class="row">${btn(icon('up'),'plan-up','icon-btn',`data-id="${r.id}" aria-label="بالاتر بردن حرکت" ${i===0?'disabled':''}`)}${btn(icon('down'),'plan-down','icon-btn',`data-id="${r.id}" aria-label="پایین‌تر بردن حرکت" ${i===list.length-1?'disabled':''}`)}${btn(icon('edit'),'plan-edit','icon-btn',`data-id="${r.id}" aria-label="ویرایش حرکت برنامه"`)}${btn(icon('trash'),'plan-remove','icon-btn',`data-id="${r.id}" aria-label="حذف حرکت برنامه"`)}</div>`:''}</div>`).join('')}</div>`:empty('روز بدون حرکت','می‌تواند روز استراحت باشد یا هنوز برنامه‌ای برایش ثبت نکرده باشی.',editable?btn('افزودن از بانک','plan-add','secondary'):'')}${editable?`<div class="form-actions">${btn(icon('copy')+' کپی برنامه از روز دیگر','plan-copy','ghost small')}</div>`:''}</section>${active?dayMuscleMapHTML(list,'عضلات برنامهٔ '+days[planDay]):''}${instructions(w)}<div class="notice">اولویت برنامه: استثنای همان روز ← استثنای همان هفته ← الگوی همان دوره. ثبت واقعی هر جلسه، مستقل از همهٔ این برنامه‌ها نگهداری می‌شود.</div>`}`;}
function periodEditor(id){const p=state.periods.find(x=>x.id===id),x=p||{name:'',startDate:C.today(),endDate:'',cycleAnchor:weekStart(C.today()),notes:''};modal(p?'ویرایش دوره':'دورهٔ تمرینی جدید',`<form id="period-form" data-id="${id||''}">${field('نام دوره',input('name',x.name,'required maxlength="120" placeholder="مثلاً دورهٔ بهار ۱۴۰۵"'))}<div class="form-grid">${field('شروع دوره ',dateInput('startDate',x.startDate,'required'))}${field('پایان دوره (اختیاری)',dateInput('endDate',x.endDate))}${field('مبدأ چرخهٔ A/B ',dateInput('cycleAnchor',x.cycleAnchor,'required'))}</div><p class="tiny muted">مبدأ چرخه با روز آغاز هفته تنظیم می‌شود. اولین نوع هفته در آن هفته فعال است.</p>${!p?`${field('کپی الگوی پایه از',`<select name="copyFrom"><option value="">بدون حرکات؛ فقط هفته‌های پیش‌فرض</option>${options(state.periods,planPeriodId)}</select>`)}<label class="check-label"><input type="checkbox" name="closePrevious" checked> دورهٔ قبلیِ بدون پایان، تا روز قبل از شروع دورهٔ جدید بسته شود.</label><p class="tiny muted">فقط الگوی حرکات و دستور هفته‌ها کپی می‌شود؛ سوابق و استثناها منتقل نمی‌شوند.</p>`:''}${field('یادداشت دوره',`<textarea maxlength="10000" name="notes" rows="3">${esc(x.notes)}</textarea>`)}<p class="notice">بازهٔ دو دوره نمی‌تواند هم‌پوشانی داشته باشد. تغییر مشخصات دوره، تاریخچهٔ ذخیره‌شده را دوباره دسته‌بندی نمی‌کند.</p><div class="form-actions"><button class="btn primary" type="submit">ذخیرهٔ دوره</button></div></form>`);}
function periodsManage(){modal('دوره‌های تمرینی',`<div class="stack">${[...state.periods].sort((a,b)=>a.startDate.localeCompare(b.startDate)).map(p=>`<div class="period-list-item"><div><b>${esc(p.name)}</b><p class="tiny muted">${periodRange(p)}</p><p class="tiny">${fa(state.sessions.filter(s=>s.periodId===p.id).length)} جلسهٔ مرتبط · ${p.weekTypes.map(w=>esc(w.name)).join(' / ')}</p></div><div class="row">${btn(icon('edit'),'period-edit','icon-btn',`data-id="${p.id}" aria-label="ویرایش دوره"`)}${btn(icon('trash'),'period-delete','icon-btn',`data-id="${p.id}" aria-label="حذف دوره"`)}</div></div>`).join('')}</div><div class="form-actions">${btn('دورهٔ جدید','period-new','primary')}</div>`);}
function historyStart(){modal('ثبت تمرین از دفتر قدیمی',`<form id="past-session-form">${field('تاریخ تمرین ',dateInput('date',C.fromPersian(1405,1,1),'required'))}<label class="check-label"><input type="checkbox" name="loadPlan"> حرکات برنامهٔ مؤثر در همان تاریخ بارگذاری شوند.</label><p class="tiny muted">ابتدا دوره‌های تاریخی را با بازه و مبدأ چرخهٔ درست تعریف کن. بدون این تیک، جلسه خالی شروع می‌شود تا آنچه واقعاً در دفتر نوشته‌ای را وارد کنی. هر تاریخی تا امروز قابل ثبت است.</p><div class="form-actions"><button class="btn primary" type="submit">باز کردن جلسهٔ گذشته</button></div></form>`);}
function workout(){const history=[...state.sessions].sort((a,b)=>b.date.localeCompare(a.date)).filter(s=>(!historyQuery||s.date===historyQuery)&&(!historyType||s.weekTypeId===historyType)&&(!historyPeriod||s.periodId===historyPeriod)&&(!historyMonth||jdate(s.date).slice(0,7)===historyMonth));const monthKeys=[...new Set(state.sessions.map(s=>jdate(s.date).slice(0,7)))].sort().reverse();return heading('تمرین امروز و تمام سوابق دفترت','دفتر تمرین','با ثبت تک‌جلسه یا ورود گروهی، تمام سوابق را در نمودارهای همین دفتر ببین.',`<div class="row wrap">${btn(icon('program')+' ثبت تمرین گذشته','past-session','secondary')}${btn('ورود گروهی از دفتر','bulk-open','secondary')}${draft?btn('کنار گذاشتن پیش‌نویس','draft-discard','ghost'):btn(icon('plus')+' جلسهٔ امروز','start','primary')}</div>`)+(draft?draftView():`<section class="card">${empty('تمرین امروز یا یک صفحه از دفتر قدیمی؟','با ثبت تک‌جلسه یا ورود گروهی، تمام سوابق را در نمودارهای همین دفتر ببین.',btn('شروع تمرین امروز','start','primary'))}</section>`)+`<section class="card" id="history"><div class="card-head"><div><h2>تاریخچهٔ تمرین‌ها</h2><p class="card-sub">${fa(history.length)} از ${fa(state.sessions.length)} جلسه</p></div>${btn(icon('download')+' خروجی CSV','csv','ghost small')}</div><div class="filter-bar">${field('تاریخ',dateInput('history-date',historyQuery,'id="history-date"'))}${field('ماه',`<select id="history-month"><option value="">همهٔ ماه‌ها</option>${monthKeys.map(k=>`<option value="${k}" ${k===historyMonth?'selected':''}>${L.monthNames()[+k.slice(5)-1]} ${localDigits(k.slice(0,4))}</option>`).join('')}</select>`)}${field('دوره',`<select id="history-period"><option value="">همهٔ دوره‌ها</option>${options(state.periods,historyPeriod)}</select>`)}${field('نوع هفته',`<select id="history-type"><option value="">همهٔ هفته‌ها</option>${options(allWeeks(),historyType)}</select>`)}${btn('حذف فیلتر','history-clear','ghost small')}</div>${history.length?history.map(historyCard).join(''):empty('جلسه‌ای در این بازه ثبت نشده','فیلترها را تغییر بده یا سوابق دفترت را وارد کن.')}</section>`;}


function bulkOpen(text=''){modal('ورود گروهی سوابق دفتر',`<form id="bulk-form"><p>هر سطر یک ست است. از جدول کپی کن یا ستون‌ها را با <b>|</b> جدا کن. تاریخ و نام حرکتِ خالی از سطر قبل تکرار می‌شوند.</p><div class="bulk-example" data-no-i18n dir="${L.dir()}">${L.t('تاریخ')} | ${L.t('حرکت')} | ${L.t('وزنه')} | ${L.t('تکرار')} | ${L.t('نوع ست')} | ${L.t('گرم‌کردن')} | ${L.t('یادداشت')}<br>${L.numericDate(C.fromPersian(1405,1,1))} | ${esc(L.exerciseName(ex('bench')))} | ${fa(60)} | ${fa(8)} | ${L.t('ست اصلی')} | ${L.t('خیر')} |<br> | | ${fa(40)} | ${fa(10)} | ${L.t('سبک و کنترل‌شده')} | ${L.t('خیر')} |</div>${field('متن سوابق',`<textarea class="bulk-input" name="text" rows="10" required maxlength="2000000" placeholder="تاریخ | حرکت | وزنه | تکرار">${esc(text)}</textarea>`)}<p class="tiny muted">حرکت یا نوع ست تازه در مرحلهٔ نهایی به بانک اضافه می‌شود. قبل از ذخیره، پیش‌نمایش و تاریخ‌های تکراری را بررسی کن. برای بخش‌های دراپ، بعداً جزئیات ست را ویرایش کن.</p><div class="form-actions"><button class="btn primary" type="submit">بررسی و پیش‌نمایش</button></div></form>`);}
function bulkPreviewView(text){const parsed=window.FitBulk.parse(text,C,{calendar:L.calendar()});if(!parsed.ok){bulkPreview=null;modal('اصلاح سطرهای ورودی',`<div class="notice warning">هیچ سابقه‌ای ذخیره نشده. خطاهای زیر را اصلاح کن.</div><ul>${parsed.errors.map(e=>`<li>سطر ${fa(e.line)}: ${esc(e.message)}</li>`).join('')}</ul><div class="form-actions">${btn('بازگشت به متن','bulk-back','secondary')}</div>`);bulkPreview={text,rows:[]};return;}bulkPreview={text,rows:parsed.rows};const dates=[...new Set(parsed.rows.map(r=>r.date))].sort(),existing=dates.filter(d=>state.sessions.some(s=>s.date===d)),newEx=[...new Set(parsed.rows.map(r=>r.exerciseName))].filter(name=>!state.exercises.some(e=>normalizedName(e.name)===normalizedName(name)));modal('پیش‌نمایش سوابق',`<div class="stats-grid">${stat('روز تمرین',fa(dates.length))}${stat('ست',fa(parsed.rows.length))}${stat('حرکت تازه',fa(newEx.length))}${stat('تاریخ دارای سابقه',fa(existing.length))}</div><p>${dateLabel(dates[0])} تا ${dateLabel(dates.at(-1))}</p>${existing.length?`<div class="notice warning">برای ${fa(existing.length)} تاریخ از قبل جلسه ثبت شده. روش برخورد را انتخاب کن:</div>${field('تاریخ‌های دارای سابقه',`<select id="bulk-existing"><option value="skip">این تاریخ‌ها وارد نشوند (جلوگیری از تکرار)</option><option value="separate">یک جلسهٔ جدا هم برای این تاریخ‌ها اضافه شود</option></select>`)}`:''}<div class="table-wrap"><table><thead><tr><th>تاریخ</th><th>حرکت</th><th>وزنه</th><th>تکرار</th><th>نوع ست</th></tr></thead><tbody>${parsed.rows.slice(0,15).map(r=>`<tr><td>${localDigits(jdate(r.date))}</td><td>${esc(r.exerciseName)}</td><td>${fa(r.weight,2)}</td><td>${fa(r.reps)}</td><td>${esc(r.setTypeName)}</td></tr>`).join('')}</tbody></table></div><p class="tiny muted">${parsed.rows.length>15?'۱۵ سطر اول نمایش داده شده. ':''}دوره و هفته از تاریخ هر جلسه و چرخهٔ دوره شناسایی می‌شوند؛ بهتر است دوره‌های تاریخی را پیش از ورود گروهی تعریف کنی. سوابق فعلی جایگزین نمی‌شوند.</p><div class="form-actions">${btn('ویرایش متن','bulk-back','secondary')}${btn('تأیید و ذخیرهٔ سوابق','bulk-commit','primary')}</div>`);}
function normalizedName(s){return String(s).normalize('NFKC').replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[\s\u200c]+/g,'').toLowerCase();}
function commitBulk(){if(!bulkPreview?.rows.length)return;const mode=$('#bulk-existing')?.value||'skip',existing=new Set(state.sessions.map(s=>s.date)),rows=bulkPreview.rows.filter(r=>mode==='separate'||!existing.has(r.date));if(!rows.length){toast('همهٔ تاریخ‌ها از قبل سابقه داشتند؛ چیزی اضافه نشد.');return;}const candidate=structuredClone(state),groups=new Map();for(const r of rows){let e=candidate.exercises.find(e=>[e.name,e.englishName,...(e.aliases||[])].filter(Boolean).some(name=>normalizedName(name)===normalizedName(r.exerciseName)));if(!e){e={id:C.uid(),name:r.exerciseName,muscle:'',equipment:'',notes:'افزوده‌شده از سوابق دفتر'};candidate.exercises.push(e);}let t=candidate.setTypes.find(t=>[t.name,L.t(t.name)].some(name=>normalizedName(name)===normalizedName(r.setTypeName)));if(!t){t={id:C.uid(),name:r.setTypeName,description:''};candidate.setTypes.push(t);}if(!groups.has(r.date)){const p=C.planForDate(candidate,r.date);groups.set(r.date,{id:C.uid(),date:r.date,weekTypeId:p.weekTypeId,weekTypeName:p.weekTypeName,periodId:p.periodId,periodName:p.periodName,protocolSnapshot:structuredClone(p.weekType),source:'notebook',dayIndex:dayOf(r.date),notes:'واردشده از دفتر',energy:0,completed:true,exercises:[]});}const s=groups.get(r.date);let se=s.exercises.find(x=>x.exerciseId===e.id);if(!se){se={id:C.uid(),exerciseId:e.id,exerciseName:e.name,sets:[]};s.exercises.push(se);}se.sets.push({id:C.uid(),typeId:t.id,typeName:t.name,warmup:r.warmup||t.id==='warmup',weight:r.weight,reps:r.reps,rir:'',tempo:'',notes:r.notes,segments:[]});}candidate.sessions.push(...groups.values());const v=C.validateImport(candidate);if(!v.ok){toast(v.error);return;}const old=state;state=candidate;if(!save()){state=old;return;}const total=groups.size;bulkPreview=null;closeModal();go('workout');render();toast(`${fa(total)} جلسه و ${fa(rows.length)} ست از دفتر اضافه شد.`);}
function previousExercise(e){if(!draft)return null;const s=[...state.sessions].filter(s=>s.id!==draft.id&&s.date<=draft.date&&s.exercises.some(x=>x.exerciseId===e.exerciseId)).sort((a,b)=>b.date.localeCompare(a.date))[0];return s?{session:s,exercise:s.exercises.find(x=>x.exerciseId===e.exerciseId)}:null;}
function previousHint(e){const p=previousExercise(e);if(!p)return '';const stats=C.sessionStats({...p.session,exercises:[p.exercise]});return `<div class="previous-hint"><span>آخرین ثبت · ${dateLabel(p.session.date,true)} · ${fa(stats.sets)} ست · بیشترین وزنه ${fa(stats.maxWeight,2)}</span>${btn('کپی ست‌های قبلی','copy-previous-sets','ghost small',`data-e="${e.id}"`)}</div>`;}

// Offline exercise catalog, facets and the shared searchable movement chooser.
const Catalog=window.FitCatalog, CATALOG_PAGE=36, CHOOSER_PAGE=24;
let libraryPage=0,libraryFilters={region:'',muscle:'',equipment:'',category:'',level:'',scope:'all',sort:'name',secondary:false};
const distinct=values=>[...new Set(values.filter(Boolean))].sort((a,b)=>L.t(a).localeCompare(L.t(b),L.locale()));
const muscleValues=()=>distinct(state.exercises.flatMap(e=>[...Catalog.muscles(e),...Catalog.secondary(e)]));
const equipmentValues=()=>distinct(state.exercises.map(e=>e.equipment));
const categoryValues=()=>distinct(state.exercises.map(e=>e.category||'شخصی'));
const regionValues=()=>distinct(state.exercises.flatMap(e=>Catalog.regions(e)));
function facetOptions(values,selected,all){return `<option value="">${all}</option>`+values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('');}
function usageMap(){const m=new Map();for(const s of state.sessions)for(const e of s.exercises){const u=m.get(e.exerciseId)||{count:0,date:''};u.count++;if(s.date>u.date)u.date=s.date;m.set(e.exerciseId,u);}return m;}
function libraryList(){const f=libraryFilters,u=usageMap();let list=Catalog.filter(state.exercises,{query:libraryQuery,region:f.region,muscle:f.muscle,equipment:f.equipment,category:f.category,level:f.level,includeSecondary:f.secondary,favorite:f.scope==='favorite',custom:f.scope==='custom'});if(f.scope==='used')list=list.filter(e=>u.has(e.id));list.sort((a,b)=>(Catalog.rank(a,libraryQuery)-Catalog.rank(b,libraryQuery))||(f.sort==='used'?((u.get(b.id)?.count||0)-(u.get(a.id)?.count||0)||L.exerciseName(a).localeCompare(L.exerciseName(b),L.locale())):f.sort==='recent'?((u.get(b.id)?.date||'').localeCompare(u.get(a.id)?.date||'')||L.exerciseName(a).localeCompare(L.exerciseName(b),L.locale())):L.exerciseName(a).localeCompare(L.exerciseName(b),L.locale())));return list;}
function starButton(e,small=false){return btn(icon(e.favorite?'star':'star-outline'),'exercise-favorite',`icon-btn favorite-button ${e.favorite?'is-favorite':''}`,`data-id="${e.id}" aria-pressed="${!!e.favorite}" aria-label="${e.favorite?'برداشتن از':'افزودن به'} علاقه‌مندی‌ها: ${esc(L.exerciseName(e))}" title="علاقه‌مندی"`);}
function library(){return heading('۸۷۶ حرکت مرجع، همراه بانک شخصی تو','بانک جامع حرکات','نام فارسی، نام انگلیسی و مترادف‌ها؛ انتخاب سریع با فیلتر عضله و وسیله.',btn(icon('plus')+' حرکت شخصی جدید','exercise-new','primary'))+`<div class="catalog-overview"><span>${icon('library')} <b>${fa(state.exercises.length)}</b> حرکت در بانک</span><span>${icon('star',16)} <b>${fa(state.exercises.filter(e=>e.favorite).length)}</b> علاقه‌مندی</span><span><b>${fa(muscleValues().length)}</b> گروه عضله</span>${btn('دربارهٔ بانک و منابع','catalog-about','ghost small')}</div><section class="card catalog-toolbar"><div class="catalog-search">${field('جست‌وجوی فارسی یا انگلیسی',input('query',libraryQuery,'id="library-query" type="search" autocomplete="off" placeholder="مثلاً پرس سینه دمبل، بارفیکس، chest یا cable…"'))}${btn('پاک کردن همهٔ فیلترها','catalog-clear','secondary small')}</div><div class="region-chips">${btn('همهٔ بدن','catalog-region',`metric-chip ${!libraryFilters.region?'active':''}`,'data-value=""')}${regionValues().map(r=>btn(esc(r),'catalog-region',`metric-chip ${libraryFilters.region===r?'active':''}`,`data-value="${esc(r)}"`)).join('')}</div><div class="catalog-filters">${field('عضلهٔ دقیق',`<select id="catalog-muscle">${facetOptions(muscleValues(),libraryFilters.muscle,'همهٔ عضلات')}</select>`)}${field('وسیله',`<select id="catalog-equipment">${facetOptions(equipmentValues(),libraryFilters.equipment,'همهٔ وسایل')}</select>`)}${field('نوع تمرین',`<select id="catalog-category">${facetOptions(categoryValues(),libraryFilters.category,'همهٔ دسته‌ها')}</select>`)}${field('سطح منبع',`<select id="catalog-level">${facetOptions(['مبتدی','متوسط','پیشرفته','نامشخص'],libraryFilters.level,'همهٔ سطوح')}</select>`)}${field('نمایش',`<select id="catalog-scope">${[['all','همهٔ حرکات'],['favorite','علاقه‌مندی‌ها'],['used','حرکات استفاده‌شده'],['custom','حرکات شخصی']].map(([v,l])=>`<option value="${v}" ${v===libraryFilters.scope?'selected':''}>${l}</option>`).join('')}</select>`)}${field('ترتیب',`<select id="catalog-sort">${[['name','نام فارسی'],['used','پراستفاده‌ترین'],['recent','آخرین استفاده']].map(([v,l])=>`<option value="${v}" ${v===libraryFilters.sort?'selected':''}>${l}</option>`).join('')}</select>`)}</div><label class="check-label"><input type="checkbox" id="catalog-secondary" ${libraryFilters.secondary?'checked':''}> فیلتر عضله، عضلات کمکی را هم در بر بگیرد</label></section><section class="card"><div id="library-results" aria-live="polite">${libraryResults()}</div></section><section class="card"><div class="card-head"><div><h2>نوع ست‌های شخصی</h2><p class="card-sub">این برچسب‌ها مستقل از بانک حرکات‌اند.</p></div>${btn('مدیریت نوع ست‌ها','types-manage','secondary small')}</div><div class="row wrap">${state.setTypes.map(t=>btn(esc(t.name),'type-edit','metric-chip',`data-id="${t.id}"`)).join('')}</div></section>`;}
function libraryResults(){const list=libraryList(),pages=Math.max(1,Math.ceil(list.length/CATALOG_PAGE));libraryPage=Math.min(libraryPage,pages-1);const part=list.slice(libraryPage*CATALOG_PAGE,(libraryPage+1)*CATALOG_PAGE);return `<div class="card-head"><div><h2>${fa(list.length)} نتیجه</h2><p class="card-sub">${list.length?`نمایش ${fa(libraryPage*CATALOG_PAGE+1)} تا ${fa(Math.min((libraryPage+1)*CATALOG_PAGE,list.length))}`:'فیلترها را تغییر بده یا حرکت شخصی تعریف کن.'}</p></div><span class="badge">جست‌وجوی آفلاین</span></div><div class="library-grid">${part.map(e=>`<article class="library-card"><div class="row spread"><span class="exercise-symbol">${icon('workout')}</span><div class="row">${starButton(e)}${btn(icon('edit'),'exercise-edit','icon-btn',`data-id="${e.id}" aria-label="ویرایش ${esc(L.exerciseName(e))}"`)}${btn(icon('trash'),'exercise-delete','icon-btn',`data-id="${e.id}" aria-label="حذف ${esc(L.exerciseName(e))}"`)}</div></div><h3>${esc(L.exerciseName(e))}</h3>${(e.englishName&&(L.language()==='fa'||e.customName))?`<p class="exercise-english" dir="ltr">${esc(e.englishName)}</p>`:''}<div class="row wrap">${Catalog.muscles(e).map(m=>`<span class="muscle-badge">${esc(m)}</span>`).join('')}<span class="tiny muted">${esc(e.equipment||'نامشخص')}</span></div><div class="row wrap catalog-meta"><span class="badge">${esc(e.category||'شخصی')}</span>${e.level?`<span class="tiny muted">${esc(e.level)}</span>`:''}</div><div class="catalog-card-actions">${btn('اجرا و جزئیات','exercise-info','ghost small',`data-id="${e.id}"`)}${btn(icon('plus')+' به جلسه','catalog-use','secondary small',`data-id="${e.id}" aria-label="افزودن ${esc(L.exerciseName(e))} به جلسه"`)}</div></article>`).join('')}</div>${!list.length?empty('حرکتی مطابق این فیلترها پیدا نشد','واژهٔ کوتاه‌تر، نام انگلیسی یا یک فیلتر کمتر را امتحان کن.',btn('پاک کردن فیلترها','catalog-clear','secondary')):''}<div class="catalog-pagination">${btn('صفحهٔ قبل','catalog-page','secondary small',`data-page="${libraryPage-1}" ${libraryPage===0?'disabled':''}`)}<span class="tiny muted">صفحهٔ ${fa(libraryPage+1)} از ${fa(pages)}</span>${btn('صفحهٔ بعد','catalog-page','secondary small',`data-page="${libraryPage+1}" ${libraryPage>=pages-1?'disabled':''}`)}</div>`;}
function updateLibrary(){const target=$('#library-results');if(target)target.innerHTML=libraryResults();}
function catalogAbout(){modal('دربارهٔ بانک حرکات',`<p>تمام ${fa(Catalog.count)} رکورد مجموعهٔ عمومی Free Exercise DB به بانک اضافه شده‌اند؛ نام‌های فارسی و نام‌های جایگزین برای جست‌وجو آماده شده‌اند.</p><p class="tiny muted">دسته‌بندی عضلات اصلی و کمکی، وسیله، نوع تمرین و سطح از دادهٔ منبع گرفته شده است و قابل ویرایش است. این فهرست گسترده است؛ نام‌گذاری گونه‌های تمرین می‌تواند متفاوت باشد.</p><div class="stack"><a href="${Catalog.source}" target="_blank" rel="noopener noreferrer">منبع: Free Exercise DB</a><a href="${Catalog.license}" target="_blank" rel="noopener noreferrer">مجوز منبع: Unlicense</a></div><p class="tiny muted">تاریخ دریافت: ${L.numericDate('2026-11-03')} · بانک و جست‌وجو در همین فایل ذخیره شده‌اند؛ برای باز کردن لینک منبع اینترنت لازم است.</p><div class="form-actions">${btn('بستن','close','primary')}</div>`);}
function exerciseInfo(id){const e=ex(id);if(!e)return;const u=usageMap().get(id),source=Catalog.sourceUrl(e);modal(esc(L.exerciseName(e)),`${movementMedia(e)}${(e.englishName&&(L.language()==='fa'||e.customName))?`<p class="exercise-english" dir="ltr">${esc(e.englishName)}</p>`:''}<div class="catalog-detail-grid">${[['عضلات اصلی',Catalog.muscles(e).join('، ')||'نامشخص'],['عضلات کمکی',Catalog.secondary(e).join('، ')||'ثبت نشده'],['وسیله',e.equipment||'نامشخص'],['نوع تمرین',e.category||'شخصی'],['سطح در منبع',e.level||'نامشخص'],['ساختار حرکت',e.mechanic||'نامشخص'],['نوع نیرو',L.forceLabel(e.force)],['سابقهٔ استفاده',u?fa(u.count)+' جلسه · آخرین بار '+dateLabel(u.date,true):'هنوز در جلسه‌ای ثبت نشده']].map(([k,v])=>`<div><span>${k}</span><b>${esc(v)}</b></div>`).join('')}</div>${e.aliases?.length?`<h3>نام‌های دیگر و عبارت‌های جست‌وجو</h3><p class="tiny muted" data-help-visible>${e.aliases.map(esc).join(' · ')}</p>`:''}${e.notes?`<div class="callout"><b>یادداشت شخصی</b><p class="user-text" data-no-i18n>${esc(e.notes)}</p></div>`:''}${source?`<p class="tiny"><a href="${source}" target="_blank" rel="noopener noreferrer">رکورد و توضیح اصلی حرکت در منبع</a></p>`:''}<div class="form-actions">${starButton(e)}${btn('ویرایش حرکت','exercise-edit','secondary',`data-id="${e.id}"`)}${btn('افزودن به جلسه','catalog-use','primary',`data-id="${e.id}"`)}</div>`);}
function exerciseEditor(id){const x=ex(id)||{name:'',englishName:'',muscle:'',equipment:'',notes:'',aliases:[],category:'شخصی',level:'نامشخص'};modal(id?'ویرایش حرکت':'حرکت شخصی جدید',`<form id="exercise-form" data-id="${id||''}"><div class="form-grid">${field('نام فارسی حرکت',input('name',x.name,'required maxlength="200"'))}${field('نام انگلیسی (اختیاری)',input('englishName',x.englishName||'','maxlength="200" dir="ltr"'))}${field('عضله / گروه اصلی',input('muscle',Catalog.muscles(x).join('، '),'maxlength="200" list="exercise-muscles" placeholder="چند عضله را با ، جدا کن"'))}${field('وسیله',input('equipment',x.equipment,'maxlength="200" list="exercise-equipment"'))}${field('نوع تمرین',`<select name="category">${facetOptions(distinct([...categoryValues(),'شخصی']),x.category||'شخصی','انتخاب دسته')}</select>`)}${field('سطح',`<select name="level">${facetOptions(['مبتدی','متوسط','پیشرفته'],x.level||'نامشخص','نامشخص')}</select>`)}</div><datalist id="exercise-muscles">${muscleValues().map(m=>`<option value="${esc(m)}">`).join('')}</datalist><datalist id="exercise-equipment">${equipmentValues().map(m=>`<option value="${esc(m)}">`).join('')}</datalist>${field('عضلات کمکی (اختیاری)',input('secondaryMuscles',Catalog.secondary(x).join('، '),'maxlength="1000" placeholder="با ، جدا کن"'))}${field('نام‌های دیگر و مترادف‌ها',input('aliases',(x.aliases||[]).join('، '),'maxlength="3000" placeholder="مثلاً قایقی، زیربغل قایقی، seated row"'))}${field('یادداشت شخصی',`<textarea name="notes" maxlength="10000" rows="3">${esc(x.notes)}</textarea>`)}<label class="check-label"><input type="checkbox" name="favorite" ${x.favorite?'checked':''}> در علاقه‌مندی‌ها باشد</label><div class="form-actions"><button type="submit" class="btn primary">ذخیرهٔ حرکت</button></div></form>`);}
function chooserHTML(selected=''){return `<div class="catalog-chooser" data-chooser data-page="0"><input type="hidden" name="exerciseId" value="${esc(selected)}"><div class="chooser-selected" data-chooser-selected role="status">${chooserSelected(selected)}</div>${field('جست‌وجوی حرکت',input('chooserQuery','','type="search" data-chooser-query autocomplete="off" placeholder="نام فارسی، انگلیسی یا عضله…"'))}<div class="chooser-filters">${field('عضله',`<select data-chooser-filter="muscle">${facetOptions(muscleValues(),'','همهٔ عضلات')}</select>`)}${field('وسیله',`<select data-chooser-filter="equipment">${facetOptions(equipmentValues(),'','همهٔ وسایل')}</select>`)}</div><details class="chooser-more"><summary>دسته و فیلترهای بیشتر</summary><div class="chooser-filters">${field('بخش بدن',`<select data-chooser-filter="region">${facetOptions(regionValues(),'','همهٔ بدن')}</select>`)}${field('نوع تمرین',`<select data-chooser-filter="category">${facetOptions(categoryValues(),'','همهٔ دسته‌ها')}</select>`)}</div></details><div class="row spread"><label class="check-label"><input type="checkbox" data-chooser-favorite> فقط علاقه‌مندی‌ها</label>${btn('پاک کردن فیلتر','chooser-clear','ghost small')}</div><div data-chooser-results>${chooserResults({query:'',muscle:'',equipment:'',selected,page:0})}</div></div>`;}
function chooserSelected(id){const e=ex(id);return e?`<span class="tiny muted">حرکت انتخاب‌شده</span><b>${esc(L.exerciseName(e))}</b>${(e.englishName&&(L.language()==='fa'||e.customName))?`<small dir="ltr">${esc(e.englishName)}</small>`:''}`:'<span class="muted">یک حرکت از نتیجه‌ها انتخاب کن.</span>';}
function chooserValues(root){const f={query:root.querySelector('[data-chooser-query]').value,favorite:root.querySelector('[data-chooser-favorite]').checked,selected:root.querySelector('[name=exerciseId]').value,page:+root.dataset.page||0};for(const el of root.querySelectorAll('[data-chooser-filter]'))f[el.dataset.chooserFilter]=el.value;return f;}
function chooserResults(f){const u=usageMap(),list=Catalog.filter(state.exercises,f).sort((a,b)=>Catalog.rank(a,f.query)-Catalog.rank(b,f.query)||Number(!!b.favorite)-Number(!!a.favorite)||(u.get(b.id)?.count||0)-(u.get(a.id)?.count||0)||L.exerciseName(a).localeCompare(L.exerciseName(b),L.locale())),pages=Math.max(1,Math.ceil(list.length/CHOOSER_PAGE)),page=Math.min(f.page||0,pages-1),part=list.slice(page*CHOOSER_PAGE,(page+1)*CHOOSER_PAGE);return `<div class="chooser-result-head"><span>${fa(list.length)} حرکت پیدا شد</span><span>صفحهٔ ${fa(page+1)} از ${fa(pages)}</span></div><div class="chooser-results" role="listbox" aria-label="نتیجه‌های انتخاب حرکت">${part.map(e=>`<button type="button" class="chooser-choice ${e.id===f.selected?'selected':''}" role="option" aria-selected="${e.id===f.selected}" data-act="chooser-select" data-id="${e.id}"><span><b>${esc(L.exerciseName(e))}</b>${(e.englishName&&(L.language()==='fa'||e.customName))?`<small dir="ltr">${esc(e.englishName)}</small>`:''}<span class="tiny muted">${Catalog.muscles(e).map(esc).join('، ')} · ${esc(e.equipment||'نامشخص')}</span></span><span class="chooser-choice-mark">${e.id===f.selected?icon('check',16):e.favorite?icon('star',16):icon('plus',16)}</span></button>`).join('')}${!part.length?'<p class="tiny muted">نتیجه‌ای نیست؛ فیلترها را کمتر کن یا نام انگلیسی را جست‌وجو کن.</p>':''}</div><div class="catalog-pagination">${btn('قبلی','chooser-page','ghost small',`data-page="${page-1}" ${page===0?'disabled':''}`)}${btn('بعدی','chooser-page','ghost small',`data-page="${page+1}" ${page>=pages-1?'disabled':''}`)}</div>`;}
function updateChooser(root){root.querySelector('[data-chooser-results]').innerHTML=chooserResults(chooserValues(root));}
function chooseExercise(){modal('انتخاب حرکت برای جلسه',`<form id="draft-exercise-form">${chooserHTML('')}<div class="form-actions">${btn('تعریف حرکت شخصی','exercise-new','ghost')}<button class="btn primary" type="submit">افزودن حرکت با ۲ ست اصلی</button></div></form>`);$('#modal').classList.add('catalog-modal');}

function skippedExerciseCard(e,ei){return `<section class="card exercise-card exercise-skipped"><div class="exercise-top"><div class="row"><span class="exercise-number">${fa(ei+1)}</span><div><h3 class="exercise-name" data-no-i18n>${esc(exName(e))}</h3><span class="badge">انجام نشد</span></div></div>${btn(icon('trash'),'draft-remove-exercise','icon-btn',`data-e="${e.id}" aria-label="حذف حرکت از جلسه"`)}</div><p class="skipped-note">کاربر تأیید کرده که این حرکت انجام نشده است.</p><p class="tiny muted">${fa(0)} ست · ${fa(0)} تکرار · ${fa(0)} حجم</p>${btn('ویرایش مقادیر','exercise-resume','secondary small',`data-e="${e.id}"`)}</section>`;}






function dateValue(el){if(!el)return '';if(el.dataset.iso&&el.value===L.numericDate(el.dataset.iso))return el.dataset.iso;return el.value.trim()?L.parseDate(el.value):'';}
function orderedDayIndexes(){return Array.from({length:7},(_,i)=>(i+L.firstDay())%7);}
function weekStrip(selected,act){return `<div class="week-strip">${orderedDayIndexes().map(i=>`<button class="day-button ${i===selected?'active':''} ${i===dayOf(C.today())?'today':''}" data-act="${act}" data-day="${i}"><span>${L.weekday(i)}</span><small>${fa((programContext().plans[planWeek]?.[i]||[]).length)} حرکت</small></button>`).join('')}</div>`;}
function calendarStrip(){const start=weekStart(planDate);return `<div class="week-strip">${orderedDayIndexes().map((index,offset)=>{const date=C.addDays(start,offset),p=C.periodForDate(state,date),r=C.planForDate(state,date);return `<button class="day-button ${date===planDate?'active':''} ${date===C.today()?'today':''}" data-act="plan-date-day" data-date="${date}" ${p?.id!==planPeriodId?'disabled':''}><span>${L.weekday(index)}</span><small data-no-i18n>${dateLabel(date,true)}</small><small>${fa(r.exercises.length)} حرکت ${r.source==='day'?'•':''}</small></button>`;}).join('')}</div>`;}

// Calendar controls. Insert inside the app closure before Event dispatch.
// A second dialog preserves unsaved values in the app's ordinary form dialog.
let jpControlSequence=0,jpDialog=null,jpTarget=null,jpYear=1405,jpMonth=1,jpSelected='',jpCalendar='persian';
const jpFallbackMonths=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];
function jpLocale(){return window.FitLocale;}
function jpT(value){const locale=jpLocale();return locale&&locale.t?locale.t(value):value;}
function jpLanguage(){const locale=jpLocale();return locale&&locale.language?locale.language():'fa';}
function jpFirstDay(){const locale=jpLocale(),value=locale&&locale.firstDay?Number(locale.firstDay()):0;return Number.isInteger(value)&&value>=0&&value<=6?value:0;}
function jpNumeric(value){const locale=jpLocale();return locale&&locale.numericDate?locale.numericDate(value):localDigits(jdate(value));}
function jpParts(value,calendar=jpCalendar){return C.calendarParts?C.calendarParts(value,calendar):C.toPersianParts(value);}
function jpFrom(year,month,day,calendar=jpCalendar){return C.fromCalendar?C.fromCalendar(year,month,day,calendar):C.fromPersian(year,month,day);}
function jpDigits(value){return L.number(value,0,false);}
function jpYearRange(){return jpCalendar==='gregory'?[1900,2200]:jpCalendar==='islamic-civil'?[1300,1700]:[1300,1600];}
function jpCalendarName(){return jpT(jpCalendar==='gregory'?'میلادی':jpCalendar==='islamic-civil'?'هجری قمری محاسباتی':'شمسی');}
function jpMonthNames(){const locale=jpLocale();return locale&&locale.monthNames?locale.monthNames(jpCalendar):jpFallbackMonths;}
function jpInputIso(target){
  const stored=target.dataset.iso&&jpParts(target.dataset.iso,'gregory')?target.dataset.iso:'';
  if(stored&&target.value===jpNumeric(stored))return stored;
  const locale=jpLocale(),visible=target.value?(locale&&locale.parseDate?locale.parseDate(target.value):parseJDate(target.value)):'';
  return visible||stored;
}

function dateInput(name,value='',attrs=''){
  // attrs are authored by the application, rather than loaded from exercise data.
  let clean=String(attrs).replace(/(^|\s)(?:type|inputmode|readonly|data-jdate|data-iso|aria-haspopup|aria-controls)\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi,' ');
  clean=clean.replace(/(^|\s)readonly(?=\s|$)/gi,' ');
  let match=clean.match(/(?:^|\s)id\s*=\s*(?:"([^"]+)"|'([^']+)'|([^\s>]+))/i);
  let controlId=match&&(match[1]||match[2]||match[3]);
  if(!controlId){
    controlId=clean.includes('data-draft="date"')?'draft-date':'jalali-control-'+(++jpControlSequence);
    clean+=' id="'+esc(controlId)+'"';
  }
  if(!clean.includes('data-allow-future="true"')&&(name==='date'||/id="(?:comparison-date|progress-from|progress-to)"/.test(clean))&&!clean.includes('data-max='))clean+=' data-max="'+C.today()+'"';if(/id="progress-from"/.test(clean)&&progressTo){clean=clean.replace(/ data-max="[^"]*"/g,'');clean+=' data-max="'+progressTo+'"';}if(/id="progress-to"/.test(clean)&&progressFrom)clean+=' data-min="'+progressFrom+'"';const shown=value?jpNumeric(value):'';
  const calendarIcon=icon('calendar',18);
  return `<span class="date-entry"><input type="text" name="${esc(name)}" value="${esc(shown)}" data-iso="${esc(value||'')}" readonly inputmode="none" data-jdate dir="ltr" aria-haspopup="dialog" aria-controls="date-modal" placeholder="${esc(jpT('انتخاب تاریخ'))}" ${clean}><button type="button" class="btn secondary small date-open-button" data-act="date-open" data-target="${esc(controlId)}" aria-label="${esc(jpT('باز کردن تقویم'))}" aria-haspopup="dialog" aria-controls="date-modal">${calendarIcon}<span>${esc(jpT('تقویم'))}</span></button></span>`;
}

function jpEnsureDialog(){
  if(jpDialog&&jpDialog.isConnected)return jpDialog;
  const existing=document.getElementById('date-modal');
  if(existing){jpDialog=existing;return jpDialog;}
  jpDialog=document.createElement('dialog');
  jpDialog.id='date-modal';
  jpDialog.className='modal jalali-modal';
  jpDialog.setAttribute('dir',document.documentElement.dir||'rtl');
  jpDialog.setAttribute('aria-labelledby','jp-dialog-title');
  document.body.appendChild(jpDialog);
  jpDialog.addEventListener('cancel',event=>{event.preventDefault();closeDatePicker();});
  return jpDialog;
}

function jpParseBound(value){
  if(!value)return '';
  const locale=jpLocale();
  return jpParts(value,'gregory')?value:locale&&locale.parseDate?locale.parseDate(value):parseJDate(value);
}

function jpWithinBounds(value){
  const min=jpParseBound(jpTarget?.dataset.min||''),max=jpParseBound(jpTarget?.dataset.max||'');
  return !!value&&(!min||value>=min)&&(!max||value<=max);
}

function openDatePicker(targetId){
  const target=document.getElementById(targetId);
  if(!target||target.tagName!=='INPUT'||!target.hasAttribute('data-jdate')||target.disabled)return;
  const locale=jpLocale();
  jpCalendar=locale&&locale.calendar?locale.calendar():'persian';
  const selected=jpInputIso(target),parts=jpParts(selected||C.today());
  if(!parts)return;
  const range=jpYearRange();
  jpTarget=target;
  jpSelected=selected;
  jpYear=Math.min(range[1],Math.max(range[0],parts.year));
  jpMonth=parts.month;
  const dialog=jpEnsureDialog();
  renderDatePicker();
  if(!dialog.open)dialog.showModal();
  const focusDay=dialog.querySelector('.jp-day.selected:not(:disabled)')||dialog.querySelector('.jp-day.today:not(:disabled)')||dialog.querySelector('.jp-day:not(:disabled)');
  if(focusDay)focusDay.focus({preventScroll:true});
}

function renderDatePicker(){
  if(!jpTarget||!jpTarget.isConnected){closeDatePicker(false);return;}
  const dialog=jpEnsureDialog(),first=jpFrom(jpYear,jpMonth,1),range=jpYearRange(),monthNames=jpMonthNames();
  if(!first)return;
  dialog.setAttribute('dir',document.documentElement.dir||'rtl');
  const firstDay=jpFirstDay(),offset=(((new Date(first+'T12:00:00').getDay()+1)%7)-firstDay+7)%7;
  let count=31;while(count>0&&!jpFrom(jpYear,jpMonth,count))count--;
  const today=C.today();
  const leading=Array.from({length:offset},()=>'<span class="jp-empty" aria-hidden="true"></span>').join('');
  const grid=Array.from({length:count},(_,index)=>{
    const day=index+1,iso=jpFrom(jpYear,jpMonth,day),selected=iso===jpSelected,current=iso===today;
    const label=`${jpDigits(day)} ${monthNames[jpMonth-1]} ${jpDigits(jpYear)}${current?'، '+jpT('امروز'):''}`;
    return `<button type="button" class="jp-day${selected?' selected':''}${current?' today':''}" data-act="jp-day" data-iso="${iso}" aria-label="${esc(label)}" aria-pressed="${selected?'true':'false'}" ${current?'aria-current="date"':''} ${jpWithinBounds(iso)?'':'disabled'}>${jpDigits(day)}</button>`;
  }).join('');
  const years=Array.from({length:range[1]-range[0]+1},(_,i)=>i+range[0]).map(y=>`<option value="${y}" ${y===jpYear?'selected':''}>${jpDigits(y)}</option>`).join('');
  const monthOptions=monthNames.map((name,index)=>`<option value="${index+1}" ${index+1===jpMonth?'selected':''}>${esc(name)}</option>`).join('');
  const min=jpParseBound(jpTarget.dataset.min||''),max=jpParseBound(jpTarget.dataset.max||'');
  const bounds=min||max?`<p class="tiny muted">${min?esc(jpT('از'))+' '+esc(jpNumeric(min)):''}${min&&max?' · ':''}${max?esc(jpT('تا'))+' '+esc(jpNumeric(max)):''}</p>`:'';
  const weekdayStart=C.weekStart(C.today()),weekdays=Array.from({length:7},(_,i)=>{
    const date=new Date(C.addDays(weekdayStart,(i+firstDay)%7)+'T12:00:00'),language=jpLanguage();
    return {short:new Intl.DateTimeFormat(language,{weekday:'short'}).format(date),long:new Intl.DateTimeFormat(language,{weekday:'long'}).format(date)};
  });
  const locale=jpLocale(),monthHeading=locale&&locale.date?locale.date(first,{month:'long',year:'numeric'}):monthNames[jpMonth-1]+' '+jpDigits(jpYear);
  dialog.innerHTML=`<div class="jp-head"><div><h2 id="jp-dialog-title">${esc(jpT('انتخاب تاریخ'))}</h2><p class="tiny muted">${esc(jpT('سال و ماه را انتخاب کن؛ سپس روی روز بزن.'))}</p><span class="badge">${esc(jpCalendarName())}</span></div><button type="button" class="btn icon-btn" data-act="jp-close" aria-label="${esc(jpT('بستن تقویم'))}">×</button></div><div class="modal-body"><div class="jp-controls"><button type="button" class="btn icon-btn" data-act="jp-prev" aria-label="${esc(jpT('ماه قبل'))}" ${jpYear===range[0]&&jpMonth===1?'disabled':''}>‹</button><label class="field"><span>${esc(jpT('ماه'))}</span><select id="jp-month" data-jp-month aria-label="${esc(jpT('ماه'))}">${monthOptions}</select></label><label class="field"><span>${esc(jpT('سال'))}</span><select id="jp-year" data-jp-year aria-label="${esc(jpT('سال'))}">${years}</select></label><button type="button" class="btn icon-btn" data-act="jp-next" aria-label="${esc(jpT('ماه بعد'))}" ${jpYear===range[1]&&jpMonth===12?'disabled':''}>›</button></div><div class="jp-current" aria-live="polite">${esc(monthHeading)}</div><div class="jp-grid" aria-label="${esc(jpT('روزهای ماه'))}">${weekdays.map(day=>`<span class="jp-weekday" aria-label="${esc(day.long)}">${esc(day.short)}</span>`).join('')}${leading}${grid}</div>${bounds}<div class="jp-footer"><button type="button" class="btn secondary small" data-act="jp-today">${esc(jpT('نمایش امروز'))}</button>${jpTarget.required?'':`<button type="button" class="btn ghost small" data-act="jp-clear">${esc(jpT('پاک کردن تاریخ'))}</button>`}<button type="button" class="btn ghost small" data-act="jp-close">${esc(jpT('انصراف'))}</button></div></div>`;
}

function closeDatePicker(restoreFocus=true){
  const target=jpTarget;
  jpTarget=null;
  jpSelected='';
  if(jpDialog?.open)jpDialog.close();
  // A date change can rerender the page; never focus an obsolete input.
  if(restoreFocus&&target?.isConnected&&!target.disabled)target.focus({preventScroll:true});
}

function jpCommitDate(value){
  const target=jpTarget;
  if(!target?.isConnected){closeDatePicker(false);return;}
  if(value&&!jpWithinBounds(value))return;
  if(!value&&target.required)return;
  target.dataset.iso=value||'';
  target.value=value?jpNumeric(value):'';
  // Input first lets period start dates update their cycle-anchor suggestion.
  // Change then updates session dates, calendar filters and comparisons.
  target.dispatchEvent(new Event('input',{bubbles:true}));
  target.dispatchEvent(new Event('change',{bubbles:true}));
  closeDatePicker();
}

function handleDatePickerAction(action,button){
  if(action==='date-open'){openDatePicker(button.dataset.target);return true;}
  if(!action.startsWith('jp-'))return false;
  if(action==='jp-close'){closeDatePicker();return true;}
  if(!jpTarget?.isConnected){closeDatePicker(false);return true;}
  if(action==='jp-day'){
    const iso=button.dataset.iso,parts=jpParts(iso);
    if(parts&&parts.year===jpYear&&parts.month===jpMonth&&jpWithinBounds(iso))jpCommitDate(iso);
    return true;
  }
  if(action==='jp-clear'){jpCommitDate('');return true;}
  if(action==='jp-today'){
    const parts=jpParts(C.today()),range=jpYearRange();
    if(parts){jpYear=Math.min(range[1],Math.max(range[0],parts.year));jpMonth=parts.month;renderDatePicker();}
    return true;
  }
  if(action==='jp-prev'||action==='jp-next'){
    const step=action==='jp-prev'?-1:1,range=jpYearRange(),index=(jpYear-range[0])*12+jpMonth-1+step;
    if(index>=0&&index<(range[1]-range[0]+1)*12){jpYear=range[0]+Math.floor(index/12);jpMonth=index%12+1;renderDatePicker();}
    return true;
  }
  return true;
}

document.addEventListener('click',event=>{
  const button=event.target.closest('[data-act]');
  if(button&&(button.dataset.act==='date-open'||button.dataset.act.startsWith('jp-'))){
    if(button.disabled)return;
    event.preventDefault();
    handleDatePickerAction(button.dataset.act,button);
    return;
  }
  const target=event.target.closest('input[data-jdate][readonly]');
  if(target&&!target.disabled){event.preventDefault();openDatePicker(target.id);}
});

document.addEventListener('change',event=>{
  const target=event.target;
  if(target.hasAttribute('data-jp-year')){
    const year=Number(target.value);
    const range=jpYearRange();
    if(Number.isInteger(year)&&year>=range[0]&&year<=range[1]){jpYear=year;renderDatePicker();jpDialog?.querySelector('[data-jp-year]')?.focus({preventScroll:true});}
  }else if(target.hasAttribute('data-jp-month')){
    const month=Number(target.value);
    if(Number.isInteger(month)&&month>=1&&month<=12){jpMonth=month;renderDatePicker();jpDialog?.querySelector('[data-jp-month]')?.focus({preventScroll:true});}
  }
});

document.addEventListener('keydown',event=>{
  const target=event.target;
  if(target.matches?.('input[data-jdate][readonly]')&&['Enter',' ','ArrowDown'].includes(event.key)){
    event.preventDefault();
    event.stopImmediatePropagation();
    openDatePicker(target.id);
  }
});

/* Advanced Persian reporting. Replace the previous complete reporting block. */
let progressFrom='',progressTo='',comparisonMode='matched';
let reportChartStyle='bar',reportAverage=false,reportChartSequence=0,reportComparisonTouched=false;

function reportText(value){return L.t(value);}
function reportLatin(value){return String(value??'').replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c));}
function reportDate(value){return value?reportLatin(L.numericDate(value)):'—';}
function reportDateHTML(value){return `<bdi class="report-date" data-no-i18n dir="ltr">${esc(reportDate(value))}</bdi>`;}
function reportDateRangeHTML(start,end){return start===end?reportDateHTML(start):`<span class="report-date-range">${reportDateHTML(start)}<span>تا</span>${reportDateHTML(end)}</span>`;}
function reportMetricName(key){return reportText({sessions:'جلسهٔ ثبت‌شده',completedSessions:'جلسه‌های انجام‌شده',skippedSessions:'جلسه‌های انجام‌نشده',sets:'ست اصلی انجام‌شده',completedSets:'ست اصلی انجام‌شده',skippedSets:'ست اصلی انجام‌نشده',warmupSets:'ست گرم‌کردنی انجام‌شده',warmupSkippedSets:'ست گرم‌کردنی انجام‌نشده',reps:'تکرار',volume:'حجم تمرین (کیلوگرم)',maxWeight:'بیشترین وزنه (کیلوگرم)',est1RM:'قدرت تخمینی 1RM (کیلوگرم)'}[key]||key);}
function reportValue(value,decimals=2){return value==null||!Number.isFinite(Number(value))?'—':reportLatin(fa(value,decimals));}
function reportSigned(value){return value==null?'—':`<bdi dir="ltr" data-no-i18n>${value>0?'+':''}${esc(reportValue(value,2))}</bdi>`;}
function reportSkipped(point){return (Number(point.skippedSessions)>0&&Number(point.completedSessions)===0)||(Number(point.skippedExercises)>0&&Number(point.completedExercises)===0)||(Number(point.skippedSets)>0&&Number(point.sets)===0&&Number(point.warmupSets)===0);}
function reportHasValue(point,key){return point.hasData!==false&&point[key]!==null&&point[key]!==undefined&&Number.isFinite(Number(point[key]));}
function reportStatus(point){return point.hasData===false?'بدون ثبت':reportSkipped(point)?'انجام نشد':Number(point.skippedSets)>0?'بخشی انجام شد':!Number(point.sets)&&Number(point.warmupSets)>0?'فقط گرم‌کردن':'انجام‌شده';}
function reportPeriodEnd(start,period){return period==='day'?start:period==='week'?C.addDays(start,6):C.addDays(C.calendarMonthStart(C.addDays(start,32),L.calendar()),-1);}
function reportBucket(bucket,period){
  const end=reportPeriodEnd(bucket.date,period),startText=reportDate(bucket.date),endText=reportDate(end);
  return {...bucket,label:period==='day'?startText:`${startText} — ${endText}`,axisLines:period==='day'?[startText]:[startText,endText],periodStart:bucket.date,periodEnd:end,period};
}
function reportEstimate(sessions){
  let best=null;
  for(const session of sessions)for(const exercise of session.exercises||[]){
    if(exercise.status==='skipped')continue;
    for(const set of exercise.sets||[]){
      if(set.status==='skipped'||set.warmup||set.typeId==='warmup')continue;
      for(const part of [set,...(set.segments||[])]){const reps=Number(part.reps),weight=Number(part.weight);if(reps>=1&&reps<=12&&weight>0&&Number.isFinite(weight)){const estimate=weight*(1+reps/30);best=best==null?estimate:Math.max(best,estimate);}}
    }
  }
  return best==null?null:Math.round(best*100)/100;
}
function reportBuckets(logs,period){
  const raw=C.aggregate(logs,period,L.calendar(),L.firstDay()),buckets=raw.map(bucket=>reportBucket(bucket,period));
  if(progressExercise)for(const bucket of buckets)bucket.est1RM=reportEstimate(logs.filter(log=>log.date>=bucket.periodStart&&log.date<=bucket.periodEnd));
  buckets.gapsOmitted=raw.gapsOmitted;buckets.period=period;
  return buckets;
}
function reportNiceMax(value,count=false){
  const raw=Math.max(1,Number(value)||0),unit=10**Math.floor(Math.log10(raw)),ratio=raw/unit;
  const ceiling=(ratio<=1?1:ratio<=2?2:ratio<=5?5:10)*unit;
  return count?Math.max(4,Math.ceil(ceiling/4)*4):ceiling;
}

function chart(data,key,label,kind='bar'){
  if(!Array.isArray(data)||!data.length)return empty('هنوز داده‌ای برای این نمودار نداریم','ثبت تمرین‌ها را وارد کن یا فیلتر بازه را تغییر بده.');
  const id='report-chart-'+(++reportChartSequence),isLine=kind==='line',compact=isLine&&!data.mainChart;
  const minWidth=compact?Math.max(470,Math.min(1100,data.length*80+110)):Math.max(660,Math.min(2600,data.length*92+130));
  const W=minWidth,H=compact?270:330,LX=70,RX=35,TY=35,BY=data.period&&data.period!=='day'?78:59,usableX=W-LX-RX,usableY=H-TY-BY,baseline=H-BY;
  const values=data.filter(point=>reportHasValue(point,key)).map(point=>Number(point[key])),countMetric=['sets','completedSets','skippedSets','reps','sessions','completedSessions','skippedSessions','warmupSets','warmupSkippedSets'].includes(key);
  const maximum=reportNiceMax(Math.max(0,...values)*1.04,countMetric),dateOf=point=>point.date||point.key;
  const timed=isLine&&data.length>1&&data.every(point=>/^\d{4}-\d{2}-\d{2}$/.test(dateOf(point)||''));
  const first=timed?dateOf(data[0]):'',span=timed?C.diffDays(dateOf(data.at(-1)),first):0;
  const xAt=(point,index)=>timed&&span>0?LX+10+C.diffDays(dateOf(point),first)/span*(usableX-20):LX+(index+.5)*usableX/data.length;
  const yAt=value=>TY+(1-Number(value)/maximum)*usableY;
  const points=data.map((point,index)=>({point,index,x:xAt(point,index),y:reportHasValue(point,key)?yAt(point[key]):null}));
  const paths=[],averagePaths=[],history=[];let path='',averagePath='';
  for(const item of points){
    if(item.y===null){if(path)paths.push(path);if(averagePath)averagePaths.push(averagePath);path='';averagePath='';continue;}
    path+=(path?' L':'M')+item.x+','+item.y;
    history.push(Number(item.point[key]));const recent=history.slice(-3),average=recent.reduce((a,b)=>a+b,0)/recent.length;
    averagePath+=(averagePath?' L':'M')+item.x+','+yAt(average);
  }
  if(path)paths.push(path);if(averagePath)averagePaths.push(averagePath);
  const barWidth=Math.max(3,Math.min(42,usableX/data.length*.55)),labelLimit=Math.max(2,Math.floor(usableX/(data.period==='week'?130:99)));
  const labelStep=data.length<=labelLimit?1:Math.ceil(data.length/labelLimit);
  let lastLabelX=-Infinity;
  const hasMissing=data.some(point=>point.hasData===false),hasSkipped=data.some(reportSkipped);
  return `<div class="report-chart-panel" data-chart-frame>
    <div class="chart report-chart chart-scroll" dir="ltr"><svg viewBox="0 0 ${W} ${H}" style="min-width:${W}px" role="img" aria-label="${esc(label)}">
      <defs><linearGradient id="${id}-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--report-accent,#9ac568)"/><stop offset="1" stop-color="var(--report-accent-deep,#648b3b)"/></linearGradient></defs>
      ${Array.from({length:5},(_,i)=>{const y=TY+i*usableY/4;return `<line class="chart-grid" x1="${LX}" x2="${W-RX}" y1="${y}" y2="${y}"/><text class="chart-axis" x="${LX-12}" y="${y+4}" text-anchor="end" direction="ltr" unicode-bidi="bidi-override" data-no-i18n>${esc(reportValue(maximum*(1-i/4),countMetric?0:1))}</text>`;}).join('')}
      ${isLine?paths.map(d=>`<path d="${d}" class="report-line" fill="none" stroke="var(--report-accent-deep,#648b3b)" stroke-width="3"/>`).join(''):''}
      ${reportAverage&&data.mainChart?averagePaths.map(d=>`<path d="${d}" fill="none" stroke="var(--report-average,#7f83d8)" stroke-width="2" stroke-dasharray="6 5"/>`).join(''):''}
      ${points.map(({point,index,x,y})=>{
        const status=key==='value'?'اندازه‌گیری ثبت‌شده':reportStatus(point),payload={start:dateOf(point),end:point.periodEnd||dateOf(point),label,value:reportHasValue(point,key)?Number(point[key]):null,status,sets:point.sets,skippedSets:point.skippedSets||0,reps:point.reps,volume:point.volume,maxWeight:point.maxWeight,sessions:point.sessions,hasData:point.hasData!==false,isTraining:key!=='value'};
        const color=reportSkipped(point)?'var(--report-skipped,#c18c38)':point.hasData===false?'var(--muted,#939d8a)':`url(#${id}-fill)`;
        const shape=y===null?`<circle cx="${x}" cy="${baseline}" r="5" fill="var(--surface,#fff)" stroke="${color}" stroke-width="2"/>`:isLine?`<circle cx="${x}" cy="${y}" r="5" fill="${color}" stroke="var(--surface,#fff)" stroke-width="2"/>`:Number(point[key])===0?`<circle cx="${x}" cy="${baseline}" r="5" fill="${color}"/>`:`<rect x="${x-barWidth/2}" y="${y}" width="${barWidth}" height="${baseline-y}" rx="${Math.min(8,barWidth/2)}" fill="${color}"/>`;
        const show=(index===0||index===data.length-1||index%labelStep===0)&&(index===data.length-1||points.at(-1).x-x>86)&&x-lastLabelX>86;
        if(show)lastLabelX=x;
        const annotation=data.length<=12?(point.hasData===false?'بدون ثبت':reportHasValue(point,key)?reportValue(point[key],2):'—'):'';
        const axisLines=point.axisLines||[reportDate(dateOf(point))];
        const accessible=[reportDate(dateOf(point)),label,reportHasValue(point,key)?reportValue(point[key]):'بدون مقدار',status].join(' | ');
        return `<g class="report-chart-point" data-report-point="${esc(JSON.stringify(payload))}" tabindex="0" role="button" aria-label="${esc(accessible)}" aria-describedby="${id}-tooltip">${shape}<rect x="${x-Math.max(12,usableX/data.length*.45)}" y="${TY-17}" width="${Math.max(24,usableX/data.length*.9)}" height="${usableY+28}" fill="transparent"/>${annotation?`<text class="report-value-label" x="${x}" y="${y!==null&&Number(point[key])>0?Math.max(17,y-10):baseline-14}" text-anchor="middle" direction="${point.hasData===false?'rtl':'ltr'}" unicode-bidi="bidi-override" data-no-i18n>${esc(annotation)}</text>`:''}</g>${show?axisLines.map((line,lineIndex)=>`<text class="chart-axis report-axis-date" x="${x}" y="${baseline+26+lineIndex*20}" text-anchor="middle" direction="ltr" unicode-bidi="bidi-override" data-no-i18n>${esc(line)}</text>`).join(''):''}`;
      }).join('')}
    </svg></div>
    <div class="report-hovercard" id="${id}-tooltip" role="tooltip" hidden></div>
  </div>
  <div class="report-chart-caption"><span>تاریخ‌ها به ترتیب سال / ماه / روز هستند.</span><span>برای جزئیات روی ستون یا نقطه بزن.</span></div>
  ${(hasMissing||hasSkipped||reportAverage&&data.mainChart)?`<div class="chart-legend">${hasMissing?'<span><i class="report-dot-missing"></i>بدون ثبت</span>':''}${hasSkipped?'<span><i class="report-dot-skipped"></i>انجام نشد</span>':''}${reportAverage&&data.mainChart?'<span><i class="report-dot-average"></i>میانگین 3 ثبت اخیر</span>':''}</div>`:''}
  ${data.gapsOmitted?'<p class="tiny muted">فاصله‌های بسیار طولانی فشرده شده‌اند؛ هیچ ثبت واقعی حذف نشده است.</p>':''}
  <details class="report-chart-data"><summary class="tiny muted">نمایش داده‌های نمودار</summary><div class="table-wrap"><table><thead><tr><th>تاریخ / بازه</th><th>${esc(label)}</th><th>وضعیت</th>${data.period&&data.period!=='day'?'<th>جزئیات</th>':''}</tr></thead><tbody>${data.map(point=>`<tr><td>${reportDateRangeHTML(dateOf(point),point.periodEnd||dateOf(point))}</td><td><bdi dir="ltr">${reportHasValue(point,key)?reportValue(point[key]):'—'}</bdi></td><td>${key==='value'?'اندازه‌گیری ثبت‌شده':reportStatus(point)}</td>${data.period&&data.period!=='day'?`<td>${btn('مشاهدهٔ روزهای این بازه','report-bucket','ghost small',`data-from="${point.periodStart}" data-to="${point.periodEnd}"`)}</td>`:''}</tr>`).join('')}</tbody></table></div></details>`;
}


function reportShowHover(target,event){
  const frame=target.closest('[data-chart-frame]'),tooltip=frame?.querySelector('.report-hovercard');if(!tooltip)return;
  let point;try{point=JSON.parse(target.dataset.reportPoint);}catch{return;}
  if(tooltip.dataset.point!==target.dataset.reportPoint){tooltip.innerHTML=reportHoverHTML(point);tooltip.dataset.point=target.dataset.reportPoint;}tooltip.hidden=false;
  const frameRect=frame.getBoundingClientRect(),targetRect=target.getBoundingClientRect(),width=Math.min(280,Math.max(220,frameRect.width-20));
  tooltip.style.width=width+'px';const desired=(event&&Number.isFinite(event.clientX)?event.clientX:targetRect.x+targetRect.width/2)-frameRect.x-width/2;
  tooltip.style.left=Math.max(8,Math.min(frameRect.width-width-8,desired))+'px';
  const below=targetRect.y-frameRect.y+Math.min(targetRect.height,60)+14;
  tooltip.style.top=Math.max(8,Math.min(frameRect.height-tooltip.offsetHeight-8,below))+'px';
}
function installReportInteractions(){
  if(document.documentElement.dataset.reportEvents)return;document.documentElement.dataset.reportEvents='1';
  document.addEventListener('pointerover',event=>{const target=event.target.closest('[data-report-point]');if(target)reportShowHover(target,event);});
  document.addEventListener('pointermove',event=>{const target=event.target.closest('[data-report-point]');if(target)reportShowHover(target,event);});
  document.addEventListener('focusin',event=>{const target=event.target.closest('[data-report-point]');if(target)reportShowHover(target);});
  document.addEventListener('pointerout',event=>{const frame=event.target.closest('[data-chart-frame]');if(frame&&!frame.contains(event.relatedTarget))frame.querySelector('.report-hovercard').hidden=true;});
  document.addEventListener('focusout',event=>{const frame=event.target.closest('[data-chart-frame]');if(frame&&!frame.contains(event.relatedTarget))frame.querySelector('.report-hovercard').hidden=true;});
  document.addEventListener('keydown',event=>{const target=event.target.closest('[data-report-point]');if(!target)return;if(event.key==='Enter'||event.key===' '){event.preventDefault();openReportPointDetails(target);}else if(event.key==='Escape'){target.closest('[data-chart-frame]').querySelector('.report-hovercard').hidden=true;}});
  document.addEventListener('click',event=>{
    const point=event.target.closest('[data-report-point]');if(point){openReportPointDetails(point);return;}
    const button=event.target.closest('[data-act]');if(!button)return;
    switch(button.dataset.act){
      case 'report-style':reportChartStyle=button.dataset.style==='line'?'line':'bar';render();break;
      case 'report-average':reportAverage=!reportAverage;render();break;
      case 'report-select-exercise':progressExercise=button.dataset.id;render();break;
      case 'report-heatday':progressFrom=button.dataset.date;progressTo=button.dataset.date;comparisonDate=button.dataset.date;reportComparisonTouched=true;progressRange='all';progressPeriod='day';render();document.querySelector('.report-primary-chart')?.scrollIntoView({behavior:'smooth',block:'start'});break;
    }
  });
  document.addEventListener('change',event=>{if(event.target.id==='comparison-date')reportComparisonTouched=true;});
}

function reportComparison(baseLogs){
  const last=[...baseLogs].sort((a,b)=>b.date.localeCompare(a.date))[0]?.date;
  const preferred=!reportComparisonTouched&&comparisonDate===C.today()&&last?last:comparisonDate;
  const reference=C.calendarParts(preferred,L.calendar())&&preferred<=C.today()?preferred:C.today();
  const start=progressPeriod==='day'?reference:progressPeriod==='week'?C.weekStart(reference,L.firstDay()):C.calendarMonthStart(reference,L.calendar());
  const periodEnd=reportPeriodEnd(start,progressPeriod),end=periodEnd<C.today()?periodEnd:C.today();
  const previousStart=progressPeriod==='day'?C.addDays(start,-1):progressPeriod==='week'?C.addDays(start,-7):C.calendarMonthStart(C.addDays(start,-1),L.calendar());
  const previousFullEnd=C.addDays(start,-1),matchedEnd=C.addDays(previousStart,C.diffDays(end,start));
  const previousEnd=comparisonMode==='full'?previousFullEnd:matchedEnd<previousFullEnd?matchedEnd:previousFullEnd;
  const filter=logs=>progressExercise?logs.map(session=>({...session,exercises:(session.exercises||[]).filter(item=>item.exerciseId===progressExercise)})).filter(session=>session.exercises.length):logs;
  const currentLogs=filter(baseLogs.filter(session=>session.date>=start&&session.date<=end)),previousLogs=filter(baseLogs.filter(session=>session.date>=previousStart&&session.date<=previousEnd));
  const current=C.stats(currentLogs),previous=C.stats(previousLogs),currentHas=current.sessions>0,previousHas=previous.sessions>0;
  const title={day:'روز انتخابی و روز قبل',week:'هفتهٔ انتخابی و هفتهٔ قبل',month:'ماه انتخابی و ماه قبل'}[progressPeriod];
  return `<section class="card report-compare"><div class="card-head"><div><div class="eyebrow">مقایسهٔ تقویمی</div><h2>${title}</h2><p class="card-sub">مقایسه از فیلترهای تاریخ نمودار مستقل است؛ فیلتر حرکت و دوره اعمال می‌شود.</p></div><span class="badge">${periodEnd>=C.today()?'بازهٔ جاری تا امروز':'بازهٔ کامل'}</span></div><div class="form-grid">${field('تاریخ مرجع مقایسه',dateInput('comparisonDate',reference,'id="comparison-date" required'))}${progressPeriod==='day'?'<div class="notice">ثبت روز انتخابی با ثبت روز قبل مقایسه می‌شود.</div>':field('مقایسه با',`<select id="comparison-mode"><option value="matched" ${comparisonMode==='matched'?'selected':''}>مدت مشابه بازهٔ قبل</option><option value="full" ${comparisonMode==='full'?'selected':''}>کل بازهٔ قبل</option></select>`)}</div><div class="report-compare-periods"><div><span>انتخابی</span>${reportDateRangeHTML(start,end)}</div><div><span>قبل</span>${reportDateRangeHTML(previousStart,previousEnd)}</div></div><div class="table-wrap"><table><thead><tr><th>شاخص</th><th>انتخابی</th><th>قبل</th><th>تغییر</th></tr></thead><tbody>${['sessions','sets','skippedSets','reps','volume','maxWeight'].map(key=>{
    const a=!currentHas?null:key==='maxWeight'&&!current.completedExercises?null:current[key],b=!previousHas?null:key==='maxWeight'&&!previous.completedExercises?null:previous[key];
    const change=a!=null&&b!=null?C.percentChange(a,b):null,diff=a!=null&&b!=null?a-b:null;
    return `<tr><td>${reportMetricName(key)}</td><td><bdi dir="ltr">${reportValue(a)}</bdi></td><td><bdi dir="ltr">${reportValue(b)}</bdi></td><td>${change==null?diff!=null?`<span>${diff===0?'بدون تغییر':`اختلاف ${reportSigned(diff)}`}</span>`:'<span class="muted">دادهٔ مقایسه کافی نیست</span>':`<bdi class="${change>=0?'positive':'negative'}" dir="ltr" data-no-i18n>${change>0?'+':''}${esc(reportValue(change,1))}%</bdi>`}</td></tr>`;
  }).join('')}</tbody></table></div><p class="tiny muted">روز بدون ثبت با روزی که «انجام نشد» تأیید شده فرق دارد. ست انجام‌نشده و گرم‌کردن در حجم اصلی وارد نمی‌شوند.</p></section>`;
}

function selectedExerciseReport(logs){
  const exercise=ex(progressExercise),report=C.exerciseReport(logs,progressExercise);
  const matchingLogs=logs.map(session=>({...session,exercises:(session.exercises||[]).filter(item=>item.exerciseId===progressExercise)})).filter(session=>session.exercises.length).sort((a,b)=>b.date.localeCompare(a.date));
  const series=reportBuckets(matchingLogs,'day'),estimate=reportEstimate(matchingLogs),exerciseTitle=L.exerciseName(exercise,exercise?.name)||'حرکت حذف‌شده';
  const bestVolume=matchingLogs.length?Math.max(...matchingLogs.map(session=>C.sessionStats(session).volume)):null;
  return `<section class="card report-exercise-summary"><div class="card-head"><div><div class="eyebrow">پروندهٔ حرکت</div><h2 class="user-text" data-no-i18n>${esc(exerciseTitle)}</h2><p class="card-sub">فقط ثبت‌های همین حرکت در بازهٔ انتخابی</p></div>${btn('انتخاب حرکت','report-pick','secondary small')}</div><div class="report-kpi-grid">${reportKPI('جلسهٔ دارای حرکت',report.scheduledSessions,'ثبت‌شده')}${reportKPI('جلسهٔ انجام‌شده',report.completedSessions,'با اجرای ست اصلی')}${reportKPI('جلسهٔ انجام‌نشده',report.skippedSessions,'صفر تأییدشده')}${reportKPI('ست انجام‌نشده',report.skippedSets||0,'جدا از ست اجراشده')}${reportKPI('بیشترین وزنه',report.maxWeight,'کیلوگرم')}${reportKPI('بیشترین حجم یک جلسه',bestVolume,'کیلوگرم')}${reportKPI('قدرت تخمینی 1RM',estimate,'تخمین از بخش‌های 1 تا 12 تکراری')}${reportKPI('تغییر بیشترین وزنه',report.weightChange,'آخرین ثبت نسبت به اولین ثبت',true)}</div><div class="report-date-pair"><span>اولین اجرای اصلی ${reportDateHTML(report.firstDate)}</span><span>آخرین اجرای اصلی ${reportDateHTML(report.lastDate)}</span></div></section><div class="report-charts">${[['maxWeight','روند وزنه'],['reps','روند تکرار'],['sets','روند ست اصلی'],['volume','روند حجم']].map(([key,title])=>`<section class="card"><div class="card-head"><h3>${title}</h3><span class="tiny muted">روزانه</span></div>${chart(series,key,reportMetricName(key),'line')}</section>`).join('')}</div><p class="tiny muted">قدرت تخمینی با فرمول Epley محاسبه می‌شود و نتیجهٔ آزمون واقعی بیشینه نیست. برای وزن بدن یا دستگاه‌های متفاوت، مقایسه را با شرایط یکسان انجام بده.</p>`;
}
function reportKPI(label,value,foot='',signed=false){return `<div class="report-kpi"><span>${esc(label)}</span><strong dir="ltr" data-no-i18n>${signed?reportSigned(value):reportValue(value)}</strong><small>${esc(foot)}</small></div>`;}
function reportDailyTable(logs){
  const days=C.aggregate(logs,'day',L.calendar(),L.firstDay());if(!days.length)return '';
  return `<section class="card"><details ${days.length<=31?'open':''}><summary><b>دفتر روزانهٔ گزارش</b><span class="badge">${reportValue(days.filter(day=>day.hasData).length)} روز دارای ثبت</span></summary><p class="tiny muted">خط تیره یعنی داده‌ای وجود ندارد؛ صفر تنها برای مقدار ثبت‌شده نمایش داده می‌شود. همهٔ بخش‌های دراپ، رست‌پاز و تکنیک‌های شخصی در جمع تکرار و حجم محاسبه می‌شوند.</p><div class="table-wrap"><table class="daily-report-table"><thead><tr><th>تاریخ</th><th>وضعیت</th><th>جلسه</th><th>ست انجام‌شده</th><th>ست انجام‌نشده</th><th>گرم‌کردن</th><th>تکرار</th><th>حجم (کیلوگرم)</th><th>بیشترین وزنه</th></tr></thead><tbody>${days.map(day=>`<tr data-report-date="${day.date}" class="${day.hasData===false?'report-no-entry':reportSkipped(day)?'report-skipped':''}"><td>${reportDateHTML(day.date)}</td><td><span class="report-status ${reportSkipped(day)?'is-skipped':day.hasData===false?'is-empty':''}">${reportStatus(day)}</span></td>${['sessions','sets','skippedSets','warmupSets','reps','volume','maxWeight'].map(key=>`<td><bdi dir="ltr">${day.hasData===false?'—':reportValue(day[key]??(key==='skippedSets'?0:null))}</bdi></td>`).join('')}</tr>`).join('')}</tbody></table></div></details></section>`;
}
function reportMuscleDistribution(logs){
  const muscles=new Map();for(const session of logs)for(const row of session.exercises||[]){const totals=C.sessionStats({...session,exercises:[row]}),name=ex(row.exerciseId)?.muscle||'دسته‌بندی نشده';muscles.set(name,(muscles.get(name)||0)+totals.volume);}
  const entries=[...muscles].filter(([,volume])=>volume>0).sort((a,b)=>b[1]-a[1]);if(!entries.length)return empty('هنوز حجم تمرینی ثبت نشده','با ثبت وزنه و تکرار، توزیع حجم بین گروه‌های عضلانی نمایش داده می‌شود.');
  const selected=entries.slice(0,8);if(entries.length>8)selected.push(['سایر گروه‌ها',entries.slice(8).reduce((sum,item)=>sum+item[1],0)]);
  const total=entries.reduce((sum,item)=>sum+item[1],0),max=entries[0][1];
  return `<div class="report-muscle-list">${selected.map(([name,value])=>`<div><div class="row spread"><span class="user-text" data-no-i18n>${esc(name)}</span><span><bdi dir="ltr">${reportValue(value,1)}</bdi><small> کیلوگرم · <bdi dir="ltr">${reportValue(value/total*100,1)}%</bdi></small></span></div><div class="report-muscle-track"><span style="width:${Math.min(100,value/max*100)}%"></span></div></div>`).join('')}</div><p class="tiny muted">دسته‌بندی اصلی هر حرکت استفاده می‌شود؛ حجم یک حرکت چند بار بین عضلات تکرار نمی‌شود.</p>`;
}
function reportHeatmap(logs){
  const actual=logs.map(session=>session.date).sort();if(!actual.length)return empty('تقویم تمرینت منتظر اولین ثبت است','روزهای انجام‌شده، انجام‌نشده و بدون ثبت اینجا جدا دیده می‌شوند.');
  const latest=actual.at(-1),end=C.addDays(C.weekStart(latest,L.firstDay()),6),start=C.addDays(end,-83),bins=new Map(C.aggregate(logs.filter(session=>session.date>=start),'day',L.calendar(),L.firstDay()).map(point=>[point.date,point]));
  const max=Math.max(1,...[...bins.values()].map(point=>point.volume)),cells=Array.from({length:84},(_,index)=>{const date=C.addDays(start,index),point=bins.get(date),future=date>C.today(),status=future?'روز آینده':point?reportStatus(point):'بدون ثبت',level=!point?'none':reportSkipped(point)?'skipped':Number(point.volume)>0?String(Math.max(1,Math.ceil(point.volume/max*4))):'zero';return `<button type="button" class="report-heat-cell level-${level}" data-act="report-heatday" data-date="${date}" aria-label="${esc(reportDate(date)+' | '+status)}" ${future?'disabled aria-disabled="true"':''}><span class="sr-only">${esc(reportDate(date))}</span></button>`;});
  return `<div class="report-heat-range">${reportDateRangeHTML(start,end)}<span>12 هفته تا آخرین ثبت</span></div><div class="report-heat-scroll"><div class="report-heat-labels">${Array.from({length:7},(_,i)=>`<span>${esc(L.weekday((i+L.firstDay())%7,true))}</span>`).join('')}</div><div class="report-heat-grid" dir="ltr">${cells.join('')}</div></div><div class="report-heat-legend"><span><i class="level-none"></i>بدون ثبت</span><span><i class="level-skipped"></i>انجام نشد</span><span><i class="level-1"></i>حجم کمتر</span><span><i class="level-4"></i>حجم بیشتر</span></div><p class="tiny muted">با انتخاب هر خانه، گزارش همان روز باز می‌شود. رنگ، حجم ثبت‌شده را نشان می‌دهد؛ معیار کیفیت تمرین نیست.</p>`;
}
function reportExerciseLeaderboard(logs){
  const ids=[...new Set(logs.flatMap(session=>(session.exercises||[]).map(row=>row.exerciseId)))],rows=ids.map(id=>({id,...C.exerciseReport(logs,id)})).sort((a,b)=>b.volume-a.volume||b.completedSessions-a.completedSessions);
  if(!rows.length)return '';
  return `<section class="card"><details ${rows.length<=12?'open':''}><summary><b>مقایسهٔ حرکت‌ها در این بازه</b><span class="badge">${reportValue(rows.length)} حرکت</span></summary><div class="table-wrap"><table><thead><tr><th>حرکت</th><th>جلسهٔ انجام‌شده</th><th>جلسهٔ انجام‌نشده</th><th>ست اصلی</th><th>ست انجام‌نشده</th><th>تکرار</th><th>حجم</th><th>بیشترین وزنه</th><th>پرونده</th></tr></thead><tbody>${rows.map(row=>`<tr><td class="user-text" data-no-i18n>${esc(L.exerciseName(ex(row.id),ex(row.id)?.name)||'حرکت حذف‌شده')}</td>${['completedSessions','skippedSessions','sets','skippedSets','reps','volume','maxWeight'].map(key=>`<td><bdi dir="ltr">${reportValue(row[key]??(key==='skippedSets'?0:null))}</bdi></td>`).join('')}<td>${btn('تحلیل حرکت','report-select-exercise','ghost small',`data-id="${esc(row.id)}"`)}</td></tr>`).join('')}</tbody></table></div></details></section>`;
}

function progress(){
  const today=C.today(),baseLogs=state.sessions.filter(session=>session.date<=today&&(!progressTrainingPeriod||session.periodId===progressTrainingPeriod));
  const quickFrom=progressRange==='all'?'':C.addDays(today,-Number(progressRange)+1),rangeInvalid=!!(progressFrom&&progressTo&&progressFrom>progressTo);
  const logs=rangeInvalid?[]:baseLogs.filter(session=>(!quickFrom||session.date>=quickFrom)&&(!progressFrom||session.date>=progressFrom)&&(!progressTo||session.date<=progressTo));
  const selected=ex(progressExercise),filtered=progressExercise?logs.map(session=>({...session,exercises:(session.exercises||[]).filter(item=>item.exerciseId===progressExercise)})).filter(session=>session.exercises.length):logs;
  const summary=C.stats(filtered),buckets=reportBuckets(filtered,progressPeriod);buckets.mainChart=true;
  const selectedName=progressExercise?L.exerciseName(selected,selected?.name)||'حرکت حذف‌شده':'همهٔ حرکت‌ها',periodTitle={day:'روند روزانه',week:'روند هفتگی',month:'روند ماهانه'}[progressPeriod];
  const allowedMetrics=['volume','sets','skippedSets','reps','maxWeight','sessions',...(progressExercise?['est1RM']:[])];if(!allowedMetrics.includes(progressMetric))progressMetric='volume';
  const recordedDates=filtered.map(session=>session.date).sort(),daysRegistered=new Set(recordedDates).size,activeFilters=progressRange!=='all'||progressFrom||progressTo||progressTrainingPeriod||progressExercise;
  const totalSets=summary.sets+(summary.skippedSets||0),completion=totalSets?summary.sets/totalSets*100:null;
  const note=progressPeriod==='day'?'هر ستون یک روز است؛ روز انجام‌نشده با مقدار ثبت‌شده و روز بدون ثبت با حلقهٔ خالی مشخص می‌شود.':'هر ستون مجموع ثبت‌های بازهٔ انتخابی در همان '+(progressPeriod==='week'?'هفته':'ماه')+' است؛ دو تاریخ زیر ستون، آغاز و پایان آن بازه‌اند.';
  return heading('گزارش‌های دقیق، بر پایهٔ ثبت‌های خودت','روند پیشرفت','ست‌های اصلی، بخش‌های تکنیک، روزهای بدون ثبت و ست‌های انجام‌نشده را جدا بررسی کن.',btn(icon('download')+' خروجی تمرین‌ها','csv','secondary'))+`
    <section class="card report-filter-card"><div class="filter-bar"><div class="field"><span>حرکت</span><div class="row wrap">${btn(icon('library')+` <span class="user-text" data-no-i18n>${esc(selectedName)}</span>`,'report-pick','secondary')}${progressExercise?btn('همهٔ حرکت‌ها','report-all','ghost small'):''}</div></div>${field('دورهٔ تمرینی',`<select id="progress-training-period"><option value="">همهٔ دوره‌ها</option>${options(state.periods,progressTrainingPeriod)}</select>`)}${field('بازهٔ نمودار',`<select id="progress-range">${[['30','30 روز اخیر'],['90','90 روز اخیر'],['365','یک سال اخیر'],['all','تمام تاریخچه']].map(([value,text])=>`<option value="${value}" ${progressRange===value?'selected':''}>${text}</option>`).join('')}</select>`)}</div><div class="form-grid">${field('تاریخ شروع بازه',dateInput('progressFrom',progressFrom,'id="progress-from"'))}${field('تاریخ پایان بازه',dateInput('progressTo',progressTo,'id="progress-to"'))}</div><div class="report-filter-bottom"><div class="segmented">${['day','week','month'].map(value=>`<button class="${value===progressPeriod?'active':''}" data-act="progress-period" data-value="${value}">${{day:'روزانه',week:'هفتگی',month:'ماهانه'}[value]}</button>`).join('')}</div>${activeFilters?btn('پاک کردن فیلترهای گزارش','report-reset','ghost small'):'<span class="tiny muted">همهٔ تاریخ‌های ثبت‌شده</span>'}</div><p class="tiny muted">فیلتر بازه، تاریخ شروع و پایان، دوره و حرکت هم‌زمان اعمال می‌شوند.</p></section>
    ${rangeInvalid?'<div class="notice warning">شروع بازه نباید پس از پایان آن باشد.</div>':''}
    <div class="report-kpi-grid report-overview">${reportKPI('جلسهٔ ثبت‌شده',summary.sessions,reportValue(daysRegistered)+' روز مجزا')}${reportKPI('ست اصلی انجام‌شده',summary.sets,reportValue(summary.skippedSets||0)+' ست اصلی انجام‌نشده')}${reportKPI('تکرار کل',summary.reps,'با همهٔ بخش‌های دراپ و رست‌پاز')}${reportKPI('حجم کل',summary.volume,'کیلوگرم · بدون گرم‌کردن')}${reportKPI('بیشترین وزنه',summary.completedExercises?summary.maxWeight:null,'کیلوگرم · اجرای اصلی')}${reportKPI('نسبت اجرای ست‌ها',completion,'درصد از ست‌های ثبت‌شده؛ نه برنامهٔ روزهای بدون ثبت')}</div>
    ${progressExercise?selectedExerciseReport(logs):''}
    <section class="card report-primary-chart"><div class="card-head"><div><div class="eyebrow">${reportMetricName(progressMetric)}</div><h2>${periodTitle}</h2><p class="card-sub"><span class="user-text" data-no-i18n>${esc(selectedName)}</span> · ${esc(L.calendarName())}${progressPeriod==='week'?' · شروع هفته: '+esc(L.weekday(L.firstDay())):''}</p></div>${recordedDates.length?`<div class="report-actual-range"><span>ثبت‌های نمایش‌داده‌شده</span>${reportDateRangeHTML(recordedDates[0],recordedDates.at(-1))}</div>`:''}</div><div class="report-metrics">${allowedMetrics.map(key=>`<button class="${key===progressMetric?'active':''}" data-act="progress-metric" data-value="${key}">${reportMetricName(key)}</button>`).join('')}</div><div class="report-chart-tools"><div class="segmented"><button data-act="report-style" data-style="bar" class="${reportChartStyle==='bar'?'active':''}">ستونی</button><button data-act="report-style" data-style="line" class="${reportChartStyle==='line'?'active':''}">خطی</button></div><button type="button" class="report-average-toggle ${reportAverage?'active':''}" data-act="report-average" aria-pressed="${reportAverage}">میانگین 3 ثبت اخیر</button></div><p class="report-explanation">${note}</p>${chart(buckets,progressMetric,reportMetricName(progressMetric),reportChartStyle)}<p class="tiny muted">حجم = مجموع وزنه × تکرارِ همهٔ بخش‌های انجام‌شده. هر تکنیک یک ست اصلی است؛ بخش‌های آن جداگانه به تکرار و حجم اضافه می‌شوند. گرم‌کردن و ست انجام‌نشده در این جمع وارد نمی‌شوند.</p></section>
    <div class="report-insight-grid"><section class="card"><div class="card-head"><div><h2>تقویم تداوم تمرین</h2><p class="card-sub">ثبت واقعی، روز به روز</p></div></div>${reportHeatmap(filtered)}</section><section class="card"><div class="card-head"><div><h2>توزیع حجم بین عضلات</h2><p class="card-sub">در بازه و حرکت‌های انتخاب‌شده</p></div></div>${reportMuscleDistribution(filtered)}</section></div>
    ${reportDailyTable(filtered)}${!progressExercise?reportExerciseLeaderboard(logs):''}${reportComparison(baseLogs)}`;
}
installReportInteractions();


// Explicit, reviewable repair for legacy native-date inputs. Insert inside the app closure.
let dateRepairRecords=[];
function repairText(text){return typeof L!=='undefined'&&typeof L.t==='function'?L.t(text):text;}
function suspiciousDates(){
  const records=[],firstDay=Number.isInteger(state.settings?.weekStartDay)?state.settings.weekStartDay:0;
  function inspect(kind,id,key,label,current){
    if(typeof current!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(current)||C.addDays(current,0)!==current)return;
    const [year,month,day]=current.split('-').map(Number);
    if(year<1300||year>1600)return;
    let proposed=C.fromPersian(year,month,day);
    if(!proposed)return;
    if(key==='cycleAnchor')proposed=C.weekStart(proposed,firstDay);
    if(proposed&&proposed!==current)records.push({kind,id,key,label,current,proposed});
  }
  for(const session of state.sessions||[])inspect('session',session.id,'date','جلسهٔ تمرین',session.date);
  for(const measurement of state.measurements||[])inspect('measurement',measurement.id,'date','اندازه‌گیری',measurement.date);
  if(draft)inspect('draft',draft.id,'date','پیش‌نویس',draft.date);
  inspect('settings','settings','cycleAnchor','مبدأ چرخهٔ عمومی',state.settings?.cycleAnchor);
  for(const period of state.periods||[])for(const key of ['startDate','endDate','cycleAnchor'])inspect('period',period.id,key,period.name,period[key]);
  return records;
}
function repairDisplayDate(value){try{return typeof L!=='undefined'&&typeof L.date==='function'?L.date(value):dateLabel(value);}catch{return value;}}
function dateRepairModal(){
  dateRepairRecords=suspiciousDates();
  if(!dateRepairRecords.length){toast(repairText('تاریخ مشکوکی پیدا نشد.'));return;}
  const fieldLabels={date:'تاریخ',startDate:'شروع دوره',endDate:'پایان دوره',cycleAnchor:'مبدأ چرخهٔ'};
  modal(repairText('بررسی و اصلاح تاریخ‌های نسخهٔ قبلی'),`
    <div class="notice warning">${esc(repairText('در نسخهٔ قبلی ممکن بود تاریخ شمسی به‌عنوان سال میلادی ذخیره شود. پیشنهادها فقط بازتفسیر عددهای سال، ماه و روز هستند؛ آن‌ها را با دفترت بررسی کن.'))}</div>
    <p>${esc(repairText('داده‌های قبلی بدون تأیید تغییر نمی‌کنند.'))} ${esc(repairText('فقط تاریخ‌های انتخاب‌شده اصلاح می‌شوند.'))}</p>
    <p class="tiny muted">${esc(repairText('برنامهٔ هفته، نوع هفته و دستورهای ذخیره‌شده تغییر نمی‌کنند.'))} ${esc(repairText('قبل از اصلاح یک پشتیبان بگیر.'))}</p>
    ${btn(repairText('دریافت پشتیبان'),'backup','secondary small')}
    <div class="table-wrap"><table><thead><tr><th>${esc(repairText('انتخاب'))}</th><th>${esc(repairText('مورد'))}</th><th>${esc(repairText('تاریخ ذخیره‌شده'))}</th><th>${esc(repairText('تاریخ پیشنهادی'))}</th></tr></thead><tbody>
    ${dateRepairRecords.map((record,index)=>`<tr><td><input type="checkbox" data-repair-index="${index}" checked aria-label="${esc(repairText('انتخاب تاریخ'))} ${fa(index+1)}"></td><td>${record.kind==='period'?`<span data-no-i18n>${esc(record.label)}</span>`:esc(repairText(record.label))}<small class="muted"> · ${esc(repairText(fieldLabels[record.key]||record.key))}</small></td><td>${esc(repairDisplayDate(record.current))}<small dir="ltr" data-no-i18n style="display:block">${esc(record.current)}</small></td><td>${esc(repairDisplayDate(record.proposed))}</td></tr>`).join('')}
    </tbody></table></div>
    <div class="form-actions">${btn(repairText('انصراف'),'close','secondary')}${btn(repairText('اصلاح انتخاب‌شده‌ها'),'date-repair-apply','primary')}</div>`);
}
function prepareDateRepairs(baseState,baseDraft,records,selectedIndices){
  const next=structuredClone(baseState),nextDraft=baseDraft?structuredClone(baseDraft):null,indices=[...new Set(selectedIndices)],changedSessions=new Set(),measurementDates=new Set();
  if(!indices.length)return {ok:false,error:'دست‌کم یک تاریخ را برای اصلاح انتخاب کن.'};
  const firstDay=Number.isInteger(next.settings?.weekStartDay)?next.settings.weekStartDay:0;
  for(const index of indices){
    if(!Number.isInteger(index)||index<0||index>=records.length)return {ok:false,error:'انتخاب تاریخ معتبر نیست؛ بررسی تاریخ‌ها را دوباره باز کن.'};
    const record=records[index];let target;
    if(record.kind==='session')target=next.sessions.find(item=>item.id===record.id);
    else if(record.kind==='measurement')target=next.measurements.find(item=>item.id===record.id);
    else if(record.kind==='draft')target=nextDraft?.id===record.id?nextDraft:null;
    else if(record.kind==='settings')target=next.settings;
    else if(record.kind==='period')target=next.periods.find(item=>item.id===record.id);
    if(!target||target[record.key]!==record.current)return {ok:false,error:'یکی از تاریخ‌ها از زمان پیش‌نمایش تغییر کرده است؛ بررسی را دوباره باز کن.'};
    const proposed=record.key==='cycleAnchor'?C.weekStart(record.proposed,firstDay):record.proposed;
    if(!proposed||C.addDays(proposed,0)!==proposed)return {ok:false,error:'تاریخ پیشنهادی معتبر نیست.'};
    target[record.key]=proposed;
    if((record.kind==='session'||record.kind==='draft')&&record.key==='date')target.dayIndex=(new Date(proposed+'T12:00:00').getDay()+1)%7;
    if(record.kind==='session')changedSessions.add(record.id);
    if(record.kind==='measurement')measurementDates.add(proposed);
  }
  for(const date of measurementDates)if(next.measurements.filter(item=>item.date===date).length>1)return {ok:false,error:'پس از اصلاح، دو اندازه‌گیری در یک تاریخ قرار می‌گیرند. هیچ داده‌ای جایگزین نشد؛ ابتدا آن‌ها را جداگانه بررسی کن.'};
  for(const session of next.sessions)if(changedSessions.has(session.id)&&(!Object.prototype.hasOwnProperty.call(session,'periodId')||session.periodId==='')){
    const resolved=C.planForDate(next,session.date);session.periodId=resolved.periodId;session.periodName=resolved.periodName;
  }
  const validation=C.validateImport(next);
  if(!validation.ok)return {ok:false,error:validation.error};
  return {ok:true,state:next,draft:nextDraft,changed:indices.length};
}
function applyDateRepairs(){
  const selected=[...document.querySelectorAll('#modal input[data-repair-index]:checked')].map(input=>Number(input.dataset.repairIndex));
  const prepared=prepareDateRepairs(state,draft,dateRepairRecords,selected);
  if(!prepared.ok){toast(repairText(prepared.error));return false;}
  if(!confirm(repairText('فقط تاریخ‌های انتخاب‌شده اصلاح شوند؟ برنامهٔ هفته و دستورهای ذخیره‌شده تغییر نمی‌کنند.')))return false;
  const oldState=state,oldDraft=draft;state=prepared.state;draft=prepared.draft;
  try{if(!save()){state=oldState;draft=oldDraft;return false;}}
  catch{state=oldState;draft=oldDraft;toast(repairText('اصلاح تاریخ‌ها ذخیره نشد؛ داده‌های قبلی نگه داشته شدند.'));return false;}
  saveDraft();dateRepairRecords=[];closeModal();render();toast(repairText('تاریخ‌ها اصلاح شدند.'));return true;
}

