  const m=$('#modal');m.dataset.skipIds=JSON.stringify(exercises.map(e=>e.id));m.dataset.skipMode=mode;m.dataset.skipSets=JSON.stringify(sets.map(row=>({eid:row.e.id,sid:row.s.id})));m.dataset.skipParts=JSON.stringify(parts.map(row=>({eid:row.e.id,sid:row.s.id,index:row.index})));
