function markConfirmedSkipped(ids){for(const e of draft.exercises)if(ids.includes(e.id))e.status='skipped';saveDraft();}
function saveCurrentSession(){
  if(!draft)return;
  const dateEl=document.querySelector('[data-draft="date"]'),date=dateEl?dateValue(dateEl):draft.date;
  if(!date||date>C.today()){toast('یک تاریخ معتبر تا امروز انتخاب کن.');return;}
  assignDraftDate(date);
  if(!draft.exercises.length){toast('دست‌کم یک حرکت به جلسه اضافه کن.');return;}
  const blanks=draft.exercises.filter(noValues),blankSets=[],blankParts=[];
  for(const e of draft.exercises){
    if(e.status==='skipped'||blanks.includes(e))continue;
    if(!e.sets.length){blanks.push(e);continue;}
    for(const s of e.sets){
      if(s.status==='skipped')continue;
      if(workoutSetEmpty(s)){blankSets.push({e,s});continue;}
      if(s.rir!==''&&!validNumber(s.rir,0,100,true)){toast('تکرار ذخیره باید عدد صحیح بین 0 و 100 باشد.');return;}
      for(const [index,part] of workoutParts(s).entries()){
        if(String(part.weight??'').trim()===''&&String(part.reps??'').trim()===''){blankParts.push({e,s,index});continue;}
        // A zero pair is a deliberately omitted technique part from a previously
        // confirmed save. It contributes neither repetitions nor volume.
        if(n(part.weight)===0&&n(part.reps)===0&&String(part.weight).trim()!==''&&String(part.reps).trim()!=='')continue;
        if(!validNumber(part.weight,0,10000)||!validNumber(part.reps,1,1000,true)){toast(`برای «${exName(e)}»، ست ${fa(e.sets.indexOf(s)+1)}، بخش ${fa(index+1)} وزنهٔ غیرمنفی و تکرار صحیح مثبت وارد کن؛ یا همان ست را انجام‌نشده بزن.`);return;}
      }
    }
  }
  if(blanks.length||blankSets.length||blankParts.length){confirmEmptyExercises(blanks,'save',blankSets,blankParts);return;}
  const cleaned=structuredClone(draft);cleaned.energy=n(cleaned.energy);cleaned.completed=true;
  for(const e of cleaned.exercises){
    e.exerciseName=e.exerciseName||ex(e.exerciseId)?.name;e.status=e.status==='skipped'?'skipped':'completed';
    for(const s of e.sets){
      const skipped=e.status==='skipped'||s.status==='skipped';s.status=skipped?'skipped':'completed';s.typeName=s.typeName||type(s.typeId)?.name;s.warmup=!!s.warmup;
      s.weight=skipped?0:n(s.weight);s.reps=skipped?0:n(s.reps);s.rir=skipped||s.rir===''?'':n(s.rir);s.tempo=String(s.tempo||'');s.notes=String(s.notes||'');
      s.segments=(s.segments||[]).map(part=>({...part,weight:skipped?0:n(part.weight),reps:skipped?0:n(part.reps)}));
    }
  }
  cleaned.weekTypeName=draft.weekTypeName||currentDraftWeek()?.name;cleaned.protocolSnapshot=draft.protocolSnapshot||structuredClone(currentDraftWeek());
  const previous=structuredClone(state.sessions),i=state.sessions.findIndex(s=>s.id===cleaned.id);
  if(i>=0)state.sessions[i]=cleaned;else state.sessions.push(cleaned);
  if(!save()){state.sessions=previous;return;}
  draft=null;saveDraft();closeModal();timer.end=null;timer.remaining=timer.duration;render();toast('جلسه ذخیره شد؛ تمام بخش‌های وزنه و تکرار در گزارش‌ها محاسبه شدند.');
}
function validDraft(value,base){
  try{
    const copy=structuredClone(value);copy.energy=n(copy.energy);
    for(const e of copy.exercises)for(const t of e.sets){
      t.segments??=[];
      for(const k of ['weight','reps','rir']){if(!['string','number'].includes(typeof t[k]))return false;t[k]=t[k]===''?(k==='rir'?'':0):n(t[k]);}
      for(const g of t.segments){if(!['string','number'].includes(typeof g.weight)||!['string','number'].includes(typeof g.reps))return false;g.weight=g.weight===''?0:n(g.weight);g.reps=g.reps===''?0:n(g.reps);}
    }
    return C.validateImport({...base,sessions:[...base.sessions.filter(x=>x.id!==copy.id),copy]}).ok;
  }catch{return false;}
}
function handleAdvancedWorkoutAction(a,b){
  if(!draft&&!['start'].includes(a))return false;
  const eid=b.dataset.e,sid=b.dataset.s,e=draft?.exercises.find(e=>e.id===eid),s=e?.sets.find(s=>s.id===sid);
  switch(a){
    case 'confirm-skipped':{
      const m=$('#modal'),mode=m.dataset.skipMode||'exercise';
      markConfirmedSkipped(JSON.parse(m.dataset.skipIds||'[]'));
      for(const item of JSON.parse(m.dataset.skipSets||'[]')){const row=draft.exercises.find(e=>e.id===item.eid)?.sets.find(s=>s.id===item.sid);if(row)row.status='skipped';}
      for(const item of JSON.parse(m.dataset.skipParts||'[]')){const row=draft.exercises.find(e=>e.id===item.eid)?.sets.find(s=>s.id===item.sid),part=row&&workoutParts(row)[item.index];if(part){part.weight=0;part.reps=0;}}
      saveDraft();closeModal();if(mode==='save')saveCurrentSession();else{render();toast('حرکت انجام‌نشده ثبت شد؛ تمرین همچنان باز است.');}return true;
    }
    case 'exercise-skip':if(e)confirmEmptyExercises([e],'exercise');return true;
    case 'exercise-resume':if(e){e.status='completed';if(e.sets.every(s=>s.status==='skipped'))for(const s of e.sets)s.status='completed';saveDraft();render();}return true;
    case 'set-skip':if(s){if(!workoutSetEmpty(s)&&!confirm('این ست انجام‌نشده شود؟ مقادیرش تا قبل از ذخیرهٔ نهایی برای بازگشت نگه داشته می‌شوند و در آمار محاسبه نمی‌شوند.'))return true;s.status='skipped';saveDraft();render();}return true;
    case 'set-resume':if(s){s.status='completed';e.status='completed';saveDraft();render();}return true;
    case 'draft-load-plan':applyDraftWeek(draft.weekTypeId);render();toast('برنامه و نوع ست‌های هفتهٔ انتخابی اعمال شد؛ مقادیر قبلی حفظ شدند.');return true;
    case 'segment-add':if($('#segments')?.children.length>=19){toast('هر ست حداکثر 20 بخش دارد.');return true;}return false;
    default:return false;
  }
}
function handleAdvancedWorkoutInput(t){
  if(!draft)return false;
  if(t.dataset.draft==='weekTypeId'||t.dataset.draft==='date')return true;
  if(t.hasAttribute('data-part')){
    const e=draft.exercises.find(x=>x.id===t.dataset.e),s=e?.sets.find(x=>x.id===t.dataset.s),part=s&&workoutParts(s)[n(t.dataset.part)];
    if(part){part[t.dataset.field]=t.value;s.status='completed';e.status='completed';saveDraft();refreshWorkoutNumbers();}
    return true;
  }
  if(t.dataset.set){
    const e=draft.exercises.find(x=>x.id===t.dataset.e),s=e?.sets.find(x=>x.id===t.dataset.s);if(!s)return true;
    if(t.dataset.set==='typeId')resizeSetParts(s,t.value);
    else if(t.dataset.set==='warmup'){
      s.warmup=t.checked;
      if(!t.checked&&C.setProfile(state,s.typeId).kind==='warmup'){
        const suggested=C.weekTypeSetId(state,currentDraftWeek(),0),working=state.setTypes.find(item=>item.id===suggested&&C.setProfile(state,item.id).kind==='working')||state.setTypes.find(item=>C.setProfile(state,item.id).kind==='working');
        if(working)resizeSetParts(s,working.id);
        else{s.warmup=true;toast('ابتدا در انواع ست، یک نوع با کاربرد ست اصلی تعریف کن.');}
      }
    }
    else s[t.dataset.set]=t.value;
    if(s.warmup&&(t.dataset.set==='typeId'||t.dataset.set==='warmup')){e.sets=e.sets.filter(x=>x.id!==s.id);e.sets.unshift(s);}
    saveDraft();if(t.dataset.set==='typeId'||t.dataset.set==='warmup')render();else refreshWorkoutNumbers();return true;
  }
  return false;
}
function handleAdvancedWorkoutChange(t){
  if(!draft)return false;
  if(t.dataset.draft==='weekTypeId'){
    applyDraftWeek(t.value);render();toast('هفتهٔ انتخابی و نوع ست‌های آن اعمال شد؛ مقدارهای واردشده حفظ شدند.');return true;
  }
  if(t.dataset.draft==='date'){
    const date=dateValue(t);if(!date||date>C.today()){render();toast('یک تاریخ معتبر تا امروز انتخاب کن.');return true;}
    assignDraftDate(date);saveDraft();render();return true;
  }
  if(t.dataset.set||t.hasAttribute('data-part'))return true;
  return false;
}
function handleAdvancedWorkoutSubmit(f,d){
  if(f.id!=='set-details-form')return false;
  const e=draft.exercises.find(x=>x.id===f.dataset.e),s=e?.sets.find(x=>x.id===f.dataset.s);if(!s)return true;
  const rows=[...f.querySelectorAll('[data-segment]')],segments=[];
  if(rows.length>19){toast('هر ست حداکثر 20 بخش دارد.');return true;}
  for(const row of rows){
    const weight=row.querySelector('[name=segmentWeight]').value,reps=row.querySelector('[name=segmentReps]').value;
    if(weight.trim()===''&&reps.trim()===''){segments.push({weight:'',reps:''});continue;}
    if(!validNumber(weight,0,10000)||!validNumber(reps,0,1000,true)){toast('برای هر بخش، وزنهٔ غیرمنفی و تکرار صحیح وارد کن.');return true;}
    segments.push({weight:n(weight),reps:n(reps)});
  }
  s.tempo=d.tempo.trim();s.notes=d.notes.trim();s.segments=segments;saveDraft();closeModal();render();return true;
}


// Definition editors, appearance and coach media. Runs inside the app closure.
function typeEditor(id){
  const t=type(id)||{name:'',description:'',partCount:1,kind:'working'},profile=C.setProfile(state,id);
  modal(id?'ویرایش نوع ست':'تعریف نوع ست',`<form id="type-form" data-id="${id||''}">${field('نام نوع ست',input('name',t.name,'required maxlength="80" placeholder="مثلاً رست‌پاز شخصی"'))}<div class="form-grid">${field('نقش ست',`<select name="kind"><option value="working" ${profile.kind==='working'?'selected':''}>ست اصلی</option><option value="warmup" ${profile.kind==='warmup'?'selected':''}>گرم‌کردن</option></select>`)}${field('تعداد جفت وزنه و تکرار در هر ست',number('partCount',t.partCount||profile.partCount,'required inputmode="numeric"'))}</div><p class="notice">عدد 1 یعنی یک وزنه و یک تکرار؛ عدد 3 یعنی سه بخش با وزنه و تکرار مستقل. تعداد بخش‌ها از 1 تا 20 است. دراپ، رست‌پاز و تکنیک دلخواهت را همین‌جا تعریف کن.</p>${field('راهنمای اجرای این تکنیک',`<textarea name="description" maxlength="10000" rows="4">${esc(t.description)}</textarea>`)}<p class="tiny muted">تغییر تعریف، اعداد و نوع ست‌های ثبت‌شدهٔ گذشته را عوض نمی‌کند. بخش‌های همین جلسه را هم می‌توانی کم و زیاد کنی.</p><div class="form-actions">${id?btn('حذف این نوع','type-delete','danger',`data-id="${id}"`):''}<button class="btn primary" type="submit">ذخیرهٔ نوع ست</button></div></form>`);
}
function typesManage(){modal('کتابخانهٔ نوع ست‌ها',`<p class="muted">برای هر تکنیک، نقش و تعداد بخش‌های وزنه × تکرار را مشخص کن.</p><div class="definition-grid">${state.setTypes.map(t=>{const p=C.setProfile(state,t.id);return `<article class="definition-card"><div class="row spread"><b>${esc(t.name)}</b>${btn(icon('edit'),'type-edit','icon-btn',`data-id="${t.id}" aria-label="ویرایش ${esc(t.name)}"`)}</div><span class="metric-chip">${p.kind==='warmup'?'گرم‌کردن':'ست اصلی'} · ${fa(p.partCount)} جفت وزنه و تکرار</span><p class="tiny muted" data-help-visible>${esc(t.description)}</p></article>`;}).join('')}</div><div class="form-actions">${btn(icon('plus')+' تعریف نوع ست جدید','type-new','primary')}</div>`);}
function weekTypeSelect(name,selected){return `<select name="${name}" data-week-set>${state.setTypes.filter(t=>C.setProfile(state,t.id).kind!=='warmup').map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${esc(t.name)} · ${fa(C.setProfile(state,t.id).partCount)} بخش</option>`).join('')}</select>`;}
function weekEditor(id){
  const w=week(id)||{name:'',instructions:'برای هر حرکت 2 ست اصلی؛ گرم‌کردن به تعداد لازم.',set1:'',set2:''};
  modal(id?'ویرایش هفتهٔ دوره':'هفتهٔ جدید دوره',`<form id="week-form" data-id="${id||''}">${field('نام هفته',input('name',w.name,'required maxlength="60" placeholder="A، B یا نام دلخواه"'))}<div class="week-set-presets"><h3>انتخاب خودکار ست‌های اصلی</h3><div class="form-grid">${field('نوع ست اصلی اول',weekTypeSelect('set1TypeId',C.weekTypeSetId(state,w,0)))}${field('نوع ست اصلی دوم',weekTypeSelect('set2TypeId',C.weekTypeSetId(state,w,1)))}</div><p class="tiny muted">با بارگذاری برنامه یا انتخاب این هفته در ثبت تمرین، نوع ست‌ها و تعداد بخش‌های وزنه و تکرار از این تنظیمات انتخاب می‌شوند.</p></div>${field('دستور کلی هفته',`<textarea name="instructions" maxlength="10000" rows="3">${esc(w.instructions)}</textarea>`)}<div class="form-grid">${field('راهنمای ست اول',`<textarea name="set1" maxlength="10000" rows="3">${esc(w.set1)}</textarea>`)}${field('راهنمای ست دوم',`<textarea name="set2" maxlength="10000" rows="3">${esc(w.set2)}</textarea>`)}</div><div class="form-actions"><button class="btn primary" type="submit">ذخیرهٔ هفته و نوع ست‌ها</button></div></form>`);
}
function weeksManage(){modal('هفته‌های دورهٔ '+esc(programContext().name||''),`<p class="muted">چرخهٔ هفته‌ها به ترتیب زیر تکرار می‌شود. هر هفته، نوع ست اول و دوم مستقل دارد.</p><div class="stack">${programContext().weekTypes.map((w,i)=>`<article class="week-definition"><div class="row spread"><h3>${fa(i+1)}. ${esc(w.name)}</h3><div class="row">${btn(icon('up'),'week-up','icon-btn',`data-id="${w.id}" ${i===0?'disabled':''} aria-label="بالاتر بردن هفته"`)}${btn(icon('down'),'week-down','icon-btn',`data-id="${w.id}" ${i===programContext().weekTypes.length-1?'disabled':''} aria-label="پایین‌تر بردن هفته"`)}${btn(icon('edit'),'week-edit','icon-btn',`data-id="${w.id}" aria-label="ویرایش هفته ${esc(w.name)}"`)}${btn(icon('trash'),'week-delete','icon-btn',`data-id="${w.id}" aria-label="حذف هفته"`)}</div></div><div class="row wrap">${[0,1].map(index=>`<span class="metric-chip">ست ${index+1}: ${esc(type(C.weekTypeSetId(state,w,index))?.name||'ست اصلی')}</span>`).join('')}</div></article>`).join('')}</div><div class="form-actions">${btn('انواع ست','types-manage','secondary')}${btn(icon('plus')+' هفتهٔ جدید','week-new','primary')}</div>`);}
function preferenceFields(){return `<div class="locale-grid">${field('ظاهر برنامه',`<select name="theme">${[['system','هماهنگ با دستگاه'],['light','روشن'],['dark','تاریک']].map(([v,text])=>`<option value="${v}" ${(state.settings.theme||'system')===v?'selected':''}>${text}</option>`).join('')}</select>`)}${field('نوع تقویم',`<select name="calendar">${[['persian','هجری شمسی'],['gregory','میلادی'],['islamic-civil','هجری قمری محاسباتی']].map(([v,text])=>`<option value="${v}" ${L.calendar()===v?'selected':''}>${text}</option>`).join('')}</select>`)}${field('روز آغاز هفته',`<select name="weekStartDay">${days.map((text,index)=>`<option value="${index}" ${L.firstDay()===index?'selected':''}>${text}</option>`).join('')}</select>`)}</div><p class="tiny muted">رابط فارسی است و تمام اعداد با رقم‌های انگلیسی نمایش داده می‌شوند. تقویم انتخابی روی تمام تاریخ‌ها و گزارش‌ها اعمال می‌شود.</p><p class="tiny muted">تغییر روز آغاز هفته، تاریخ جلسه‌های قبلی و استثناهای برنامه را حفظ می‌کند.</p>`;}
function savePreferences(d){if(!validNumber(d.reminderDays,1,365,true)){toast('فاصلهٔ یادآور را از 1 تا 365 روز وارد کن.');return;}const day=n(d.weekStartDay);if(!['persian','gregory','islamic-civil'].includes(d.calendar)||!['light','dark','system'].includes(d.theme)||!Number.isInteger(day)||day<0||day>6)return;const old=state;state=C.rebaseWeekStart(state,day);Object.assign(state.settings,{language:'fa',calendar:d.calendar,theme:d.theme,reminderDays:n(d.reminderDays)});if(!save()){state=old;return;}historyMonth='';planScope='';comparisonDate=C.today();render();toast('تنظیمات ذخیره شد.');}
function applyAppTheme(){const selected=state.settings.theme||'system',dark=selected==='dark'||selected==='system'&&window.matchMedia?.('(prefers-color-scheme: dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light';const toggle=$('#theme-toggle');if(toggle){toggle.innerHTML=icon(dark?'sun':'moon');toggle.setAttribute('aria-label',dark?'فعال کردن تم روشن':'فعال کردن تم تاریک');toggle.title=dark?'تم روشن':'تم تاریک';}document.querySelector('meta[name="theme-color"]')?.setAttribute('content',dark?'#111913':'#f4f4ef');}
function mediaFrames(e){if(e.mediaUrl)return [e.mediaUrl];return e.source==='free-exercise-db'&&e.sourceId?[0,1].map(index=>`https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/${encodeURIComponent(e.sourceId)}/${index}.jpg`):[];}
function movementMedia(e){const frames=mediaFrames(e);return `<section class="movement-media" data-movement-media><div class="movement-frame ${frames.length>1?'reference-frames':''}">${frames.length?frames.map((src,index)=>`<img src="${esc(src)}" alt="${esc(e.name)}${frames.length>1?'؛ وضعیت '+(index+1):''}" referrerpolicy="no-referrer" ${index?'class="second-frame"':''}>`).join(''):'<div class="media-empty">'+icon('workout')+'<p>رسانهٔ این حرکت را اضافه کن.</p></div>'}<p class="media-failed" hidden>دریافت تصویر ممکن نشد. اتصال یا نشانی رسانه را بررسی کن؛ فایل GIF مربی را هم می‌توانی جایگزین کنی.</p></div><div class="row wrap spread"><div><b>${e.mediaUrl?'رسانهٔ مربی':'تصاویر مرجع اجرای حرکت'}</b><p class="tiny muted">${esc(e.mediaCaption||(frames.length>1?'دو عکس از وضعیت‌های حرکت؛ نمایش متناوب آن‌ها، فیلم پیوسته نیست.':'GIF یا تصویر دلخواه برای همین حرکت'))}</p></div><div class="row wrap">${frames.length>1?btn('پخش دو وضعیت','media-play','secondary small'):''}${btn('افزودن یا جایگزینی GIF','media-edit','secondary small',`data-id="${e.id}"`)}</div></div>${frames.length>1?'<p class="tiny muted">تصاویر مرجع برای نمایش به اینترنت نیاز دارند. رسانهٔ بارگذاری‌شده روی همین دستگاه ذخیره می‌شود.</p>':''}${e.mediaCredit?`<p class="tiny muted" data-help-visible>منبع: ${esc(e.mediaCredit)}</p>`:frames.length>1?'<p class="tiny muted"><a href="https://github.com/yuhonas/free-exercise-db" target="_blank" rel="noopener noreferrer">منبع تصاویر: Free Exercise DB، با مجوز Unlicense</a></p>':''}</section>`;}
function mediaEditor(id){const e=ex(id);if(!e)return;modal('رسانهٔ اجرای '+esc(e.name),`<form id="media-form" data-id="${id}">${field('فایل GIF یا تصویر مربی',`<input type="file" name="mediaFile" accept="image/gif,image/png,image/jpeg,image/webp">`)}<p class="tiny muted">حداکثر اندازهٔ فایل 1 مگابایت. فایل انتخابی به همراه پشتیبان دفتر منتقل می‌شود.</p>${field('یا نشانی HTTPS تصویر یا GIF',input('mediaUrl',e.mediaUrl?.startsWith('https:')?e.mediaUrl:'','dir="ltr" placeholder="https://…" maxlength="2000"'))}${field('توضیح اجرای مربی',input('mediaCaption',e.mediaCaption||'','maxlength="1000"'))}${field('نام یا منبع رسانه',input('mediaCredit',e.mediaCredit||'','maxlength="1000"'))}<div class="media-file-preview" data-media-preview></div><div class="form-actions">${e.mediaUrl?btn('بازگرداندن تصاویر مرجع','media-reset','ghost',`data-id="${id}"`):''}<button type="submit" class="btn primary">ذخیره و جایگزینی رسانه</button></div></form>`);}
async function saveMovementMedia(f){const e=ex(f.dataset.id);if(!e)return;const data=new FormData(f),file=f.querySelector('[name="mediaFile"]').files[0];let url=String(data.get('mediaUrl')||'').trim()||e.mediaUrl||'';if(file){if(file.size>1024*1024||!['image/gif','image/png','image/jpeg','image/webp'].includes(file.type)){toast('یک فایل GIF، PNG، JPG یا WebP حداکثر 1 مگابایت انتخاب کن.');return;}url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});}if(url&&!/^https:\/\/[^\s]+$/i.test(url)&&!/^data:image\/(gif|png|jpeg|webp);base64,[a-z0-9+/]+=*$/i.test(url)){toast('نشانی رسانه باید HTTPS یا فایل تصویری معتبر باشد.');return;}const old=structuredClone(e);Object.assign(e,{mediaUrl:url,mediaCaption:String(data.get('mediaCaption')||'').trim(),mediaCredit:String(data.get('mediaCredit')||'').trim()});if(!save()){for(const key of Object.keys(e))delete e[key];Object.assign(e,old);return;}render();exerciseInfo(e.id);toast('رسانهٔ حرکت ذخیره شد.');}
function handleAdvancedDefinitionSubmit(f,d,id){if(f.id==='media-form'){saveMovementMedia(f).catch(()=>toast('خواندن رسانه ممکن نشد.'));return true;}if(f.id!=='type-form'&&f.id!=='week-form')return false;if(!d.name.trim()){toast('نام را وارد کن.');return true;}const old=structuredClone(state);if(f.id==='type-form'){if(!validNumber(d.partCount,1,20,true)||!['working','warmup'].includes(d.kind)){toast('نقش ست و تعداد بخش‌های صحیح از 1 تا 20 لازم است.');return true;}if(d.kind==='warmup'&&[state,...state.periods].some(p=>p.weekTypes.some(w=>w.set1TypeId===id||w.set2TypeId===id))){toast('این نوع برای ست اصلی هفته انتخاب شده؛ ابتدا انتخاب هفته را تغییر بده.');return true;}const value={id:id||C.uid(),name:d.name.trim(),description:d.description.trim(),partCount:n(d.partCount),kind:d.kind};if(id)Object.assign(type(id),value);else state.setTypes.push(value);}else{if(!type(d.set1TypeId)||!type(d.set2TypeId)){toast('نوع ست اول و دوم را انتخاب کن.');return true;}const value={id:id||C.uid(),name:d.name.trim(),instructions:d.instructions.trim(),set1:d.set1.trim(),set2:d.set2.trim(),set1TypeId:d.set1TypeId,set2TypeId:d.set2TypeId};if(id)Object.assign(week(id),value);else{programContext().weekTypes.push(value);programContext().plans[value.id]=Object.fromEntries(days.map((_,index)=>[index,[]]));}}if(!state.setTypes.some(t=>C.setProfile(state,t.id).kind==='working')){state=old;toast('دست‌کم یک نوع ست اصلی باید وجود داشته باشد.');return true;}if(!save()){state=old;return true;}closeModal();render();toast('تعریف ذخیره شد؛ سوابق قبلی حفظ شدند.');return true;}
function handleAdvancedDefinitionAction(a,b){const id=b.dataset.id;if(a==='theme-toggle'){const hadTheme=Object.hasOwn(state.settings,'theme'),before=state.settings.theme;state.settings.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';if(!save()){if(hadTheme)state.settings.theme=before;else delete state.settings.theme;return true;}applyAppTheme();return true;}if(a==='type-delete'){if([state,...state.periods].some(p=>p.weekTypes.some(w=>w.set1TypeId===id||w.set2TypeId===id))){toast('این نوع ست در تنظیمات یک هفته استفاده شده؛ ابتدا نوع ست آن هفته را تغییر بده.');return true;}if(state.setTypes.length===1||state.setTypes.filter(t=>C.setProfile(state,t.id).kind==='working').length===1&&C.setProfile(state,id).kind==='working'){toast('دست‌کم یک نوع ست اصلی باید باقی بماند.');return true;}return false;}if(a==='media-edit'){mediaEditor(id);return true;}if(a==='media-play'){const panel=b.closest('[data-movement-media]');panel.classList.toggle('is-playing');b.textContent=panel.classList.contains('is-playing')?'مکث':'پخش دو وضعیت';return true;}if(a==='media-reset'){const e=ex(id),old=structuredClone(e);delete e.mediaUrl;delete e.mediaCaption;delete e.mediaCredit;if(!save()){Object.assign(e,old);return true;}exerciseInfo(id);render();return true;}return false;}
function showMovementPreview(f){const file=f.querySelector('[name="mediaFile"]').files[0],box=f.querySelector('[data-media-preview]');if(!file||file.size>1024*1024||!['image/gif','image/png','image/jpeg','image/webp'].includes(file.type)){box.innerHTML='';return;}const reader=new FileReader();reader.onload=()=>{if(f.isConnected)box.innerHTML=`<img src="${esc(reader.result)}" alt="پیش‌نمایش رسانهٔ مربی">`;};reader.readAsDataURL(file);}

document.addEventListener('change',ev=>{if(ev.target.name==='mediaFile'&&ev.target.closest('#media-form'))showMovementPreview(ev.target.form);});
document.addEventListener('error',ev=>{if(ev.target.tagName==='IMG'&&ev.target.closest('[data-movement-media]')){const panel=ev.target.closest('[data-movement-media]');ev.target.hidden=true;panel.querySelector('.media-failed').hidden=false;}},true);
window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener?.('change',()=>applyAppTheme());


/* Read-only planned muscle coverage and ordinal-matched set history.
   Insert inside the main application closure after the other helper modules. */
function bodyMuscleNames(){return ['سینه','سرشانه','جلو بازو','پشت بازو','ساعد','شکم','چهارسر ران','داخل ران','خارج ران','پشت ران','باسن','ساق پا','زیربغل','میان پشت','فیله کمر','کول','گردن'];}
function bodyMuscleCanonical(value){
  const key=String(value??'').normalize('NFKC').replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/[\u200c\u200d]/g,' ').replace(/\s+/g,' ').trim().toLowerCase();
  const aliases={chest:'سینه',pectorals:'سینه',shoulders:'سرشانه',deltoids:'سرشانه','شانه':'سرشانه',biceps:'جلو بازو',triceps:'پشت بازو',forearms:'ساعد',abdominals:'شکم',abs:'شکم',quadriceps:'چهارسر ران',quads:'چهارسر ران','چهار سر ران':'چهارسر ران',adductors:'داخل ران',abductors:'خارج ران',hamstrings:'پشت ران',glutes:'باسن',calves:'ساق پا',lats:'زیربغل','زیر بغل':'زیربغل','middle back':'میان پشت','middle-back':'میان پشت','میان‌پشت':'میان پشت','lower back':'فیله کمر','lower-back':'فیله کمر','فیلهٔ کمر':'فیله کمر',traps:'کول',trapezius:'کول',neck:'گردن'};
  return (Object.hasOwn(aliases,key)?aliases[key]:'')||bodyMuscleNames().find(name=>name===key)||String(value??'').trim();
}
function bodyMuscleValues(value){return (Array.isArray(value)?value:[value]).flatMap(name=>String(name??'').split(/[،,;|\n]/)).map(name=>bodyMuscleCanonical(name)).filter(Boolean);}
function bodyExerciseForEntry(entry){const id=typeof entry==='string'?entry:entry?.exerciseId||entry?.id;return id?ex(id):null;}
function periodMuscleEntries(period){
  if(!period)return [];
  const entries=[];
  for(const week of Object.values(period.plans||{}))for(const day of Object.values(week||{}))if(Array.isArray(day))entries.push(...day);
  const inPeriod=date=>!!date&&C.addDays(date,0)===date&&(!period.startDate||date>=period.startDate)&&(!period.endDate||date<=period.endDate);
  for(const [date,day] of Object.entries(period.dayOverrides||{}))if(inPeriod(date)&&Array.isArray(day))entries.push(...day);
  const firstDay=L.firstDay();
  for(const [start,override] of Object.entries(period.weekOverrides||{})){
    if(!start||C.addDays(start,0)!==start)continue;
    for(const [day,rows] of Object.entries(override?.days||{})){
      const canonical=Number(day);if(!Number.isInteger(canonical)||canonical<0||canonical>6||!Array.isArray(rows))continue;
      const date=C.addDays(start,(canonical-firstDay+7)%7);if(inPeriod(date))entries.push(...rows);
    }
  }
  const unique=new Map();for(const entry of entries){const id=typeof entry==='string'?entry:entry?.exerciseId;if(id&&!unique.has(id))unique.set(id,entry);}
  return [...unique.values()];
}
function bodyMuscleCoverage(entries){
  const known=new Set(bodyMuscleNames()),seen=new Set(),primary=new Map(),secondary=new Map(),unknownExercises=[],missingMuscles=[];
  const add=(map,name,id)=>{if(!map.has(name))map.set(name,new Set());map.get(name).add(id);};
  for(const entry of entries||[]){
    const id=typeof entry==='string'?entry:entry?.exerciseId||entry?.id;if(!id||seen.has(id))continue;seen.add(id);
    const exercise=bodyExerciseForEntry(entry);
    if(!exercise){unknownExercises.push(id);continue;}
    const main=bodyMuscleValues(Array.isArray(exercise.primaryMuscles)&&exercise.primaryMuscles.length?exercise.primaryMuscles:exercise.muscle);
    const auxiliary=bodyMuscleValues(exercise.secondaryMuscles||[]);
    if(!main.length)missingMuscles.push(exercise.name||id);
    const mainNames=new Set(main);for(const name of mainNames)add(primary,name,id);
    for(const name of new Set(auxiliary))if(!mainNames.has(name))add(secondary,name,id);
  }
  const sort=list=>list.sort((a,b)=>a.localeCompare(b,'fa'));
  const primaryNames=sort([...primary.keys()]),secondaryNames=sort([...secondary.keys()].filter(name=>!primary.has(name)));
  const counts=Object.fromEntries(sort([...new Set([...primary.keys(),...secondary.keys()])]).map(name=>[name,{primary:primary.get(name)?.size||0,secondary:secondary.get(name)?.size||0}]));
  return {exerciseCount:seen.size,primary:primaryNames,secondary:secondaryNames,counts,unmapped:sort([...new Set([...primaryNames,...secondaryNames].filter(name=>!known.has(name)))]),unknownExercises,missingMuscles};
}
